insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('jdg-18-7','jdg','사사기',18,7,'이에 다섯 사람이 떠나 라이스에 이르러 거기 있는 백성을 본즉 염려 없이 거주하며 시돈 사람들이 사는 것처럼 평온하며 안전하니 그 땅에는 부족한 것이 없으며 부를 누리며 시돈 사람들과 거리가 멀고 어떤 사람과도 상종하지 아니함이라',7001),
('jdg-18-8','jdg','사사기',18,8,'그들이 소라와 에스다올에 돌아가서 그들의 형제들에게 이르매 형제들이 그들에게 묻되 너희가 보기에 어떠하더냐 하니',7002),
('jdg-18-9','jdg','사사기',18,9,'이르되 일어나 그들을 치러 올라가자 우리가 그 땅을 본즉 매우 좋더라 너희는 가만히 있느냐 나아가서 그 땅 얻기를 게을리 하지 말라',7003),
('jdg-18-10','jdg','사사기',18,10,'너희가 가면 평화로운 백성을 만날 것이요 그 땅은 넓고 그 곳에는 세상에 있는 것이 하나도 부족함이 없느니라 하나님이 그 땅을 너희 손에 넘겨 주셨느니라 하는지라',7004),
('jdg-18-11','jdg','사사기',18,11,'단 지파의 가족 중 육백 명이 무기를 지니고 소라와 에스다올에서 출발하여',7005),
('jdg-18-12','jdg','사사기',18,12,'올라가서 유다에 있는 기럇여아림에 진 치니 그러므로 그 곳 이름이 오늘까지 마하네 단이며 그 곳은 기럇여아림 뒤에 있더라',7006),
('jdg-18-13','jdg','사사기',18,13,'무리가 거기서 떠나 에브라임 산지 미가의 집에 이르니라',7007),
('jdg-18-14','jdg','사사기',18,14,'전에 라이스 땅을 정탐하러 갔던 다섯 사람이 그 형제들에게 말하여 이르되 이 집에 에봇과 드라빔과 새긴 신상과 부어 만든 신상이 있는 줄을 너희가 아느냐 그런즉 이제 너희는 마땅히 행할 것을 생각하라 하고',7008),
('jdg-18-15','jdg','사사기',18,15,'다섯 사람이 그 쪽으로 향하여 그 청년 레위 사람의 집 곧 미가의 집에 이르러 그에게 문안하고',7009),
('jdg-18-16','jdg','사사기',18,16,'단 자손 육백 명은 무기를 지니고 문 입구에 서니라',7010),
('jdg-18-17','jdg','사사기',18,17,'그 땅을 정탐하러 갔던 다섯 사람이 그리로 들어가서 새긴 신상과 에봇과 드라빔과 부어 만든 신상을 가져갈 때에 그 제사장은 무기를 지닌 육백 명과 함께 문 입구에 섰더니',7011),
('jdg-18-18','jdg','사사기',18,18,'그 다섯 사람이 미가의 집에 들어가서 그 새긴 신상과 에봇과 드라빔과 부어 만든 신상을 가지고 나오매 그 제사장이 그들에게 묻되 너희가 무엇을 하느냐 하니',7012),
('jdg-18-19','jdg','사사기',18,19,'그들이 그에게 이르되 잠잠하라 네 손을 입에 대라 우리와 함께 가서 우리의 아버지와 제사장이 되라 네가 한 사람의 집의 제사장이 되는 것과 이스라엘의 한 지파 한 족속의 제사장이 되는 것 중에서 어느 것이 낫겠느냐 하는지라',7013),
('jdg-18-20','jdg','사사기',18,20,'그 제사장이 마음에 기뻐하여 에봇과 드라빔과 새긴 우상을 받아 가지고 그 백성 가운데로 들어가니라',7014),
('jdg-18-21','jdg','사사기',18,21,'그들이 돌이켜서 어린 아이들과 가축과 값진 물건들을 앞세우고 길을 떠나더니',7015),
('jdg-18-22','jdg','사사기',18,22,'그들이 미가의 집을 멀리 떠난 때에 미가의 이웃집 사람들이 모여서 단 자손을 따라 붙어서',7016),
('jdg-18-23','jdg','사사기',18,23,'단 자손을 부르는지라 그들이 얼굴을 돌려 미가에게 이르되 네가 무슨 일로 이같이 모아 가지고 왔느냐 하니',7017),
('jdg-18-24','jdg','사사기',18,24,'미가가 이르되 내가 만든 신들과 제사장을 빼앗아 갔으니 이제 내게 오히려 남은 것이 무엇이냐 너희가 어찌하여 나더러 무슨 일이냐고 하느냐 하는지라',7018),
('jdg-18-25','jdg','사사기',18,25,'단 자손이 그에게 이르되 네 목소리를 우리에게 들리게 하지 말라 노한 자들이 너희를 쳐서 네 생명과 네 가족의 생명을 잃게 할까 하노라 하고',7019),
('jdg-18-26','jdg','사사기',18,26,'단 자손이 자기 길을 간지라 미가가 단 자손이 자기보다 강한 것을 보고 돌이켜 집으로 돌아갔더라',7020),
('jdg-18-27','jdg','사사기',18,27,'단 자손이 미가가 만든 것과 그 제사장을 취하여 라이스에 이르러 한가하고 걱정 없이 사는 백성을 만나 칼날로 그들을 치며 그 성읍을 불사르되',7021),
('jdg-18-28','jdg','사사기',18,28,'그들을 구원할 자가 없었으니 그 성읍이 베드르홉 가까운 골짜기에 있어서 시돈과 거리가 멀고 상종하는 사람도 없음이었더라 단 자손이 성읍을 세우고 거기 거주하면서',7022),
('jdg-18-29','jdg','사사기',18,29,'이스라엘에게서 태어난 그들의 조상 단의 이름을 따라 그 성읍을 단이라 하니라 그 성읍의 본 이름은 라이스였더라',7023),
('jdg-18-30','jdg','사사기',18,30,'단 자손이 자기들을 위하여 그 새긴 신상을 세웠고 모세의 손자요 게르솜의 아들인 요나단과 그의 자손은 단 지파의 제사장이 되어 그 땅 백성이 사로잡히는 날까지 이르렀더라',7024),
('jdg-18-31','jdg','사사기',18,31,'하나님의 집이 실로에 있을 동안에 미가가 만든 바 새긴 신상이 단 자손에게 있었더라',7025),
('jdg-19-1','jdg','사사기',19,1,'이스라엘에 왕이 없을 그 때에 에브라임 산지 구석에 거류하는 어떤 레위 사람이 유다 베들레헴에서 첩을 맞이하였더니',7026),
('jdg-19-2','jdg','사사기',19,2,'그 첩이 행음하고 남편을 떠나 유다 베들레헴 그의 아버지의 집에 돌아가서 거기서 넉 달 동안을 지내매',7027),
('jdg-19-3','jdg','사사기',19,3,'그의 남편이 그 여자에게 다정하게 말하고 그를 데려오고자 하여 하인 한 사람과 나귀 두 마리를 데리고 그에게로 가매 여자가 그를 인도하여 아버지의 집에 들어가니 그 여자의 아버지가 그를 보고 기뻐하니라',7028),
('jdg-19-4','jdg','사사기',19,4,'그의 장인 곧 그 여자의 아버지가 그를 머물게 하매 그가 삼 일 동안 그와 함께 머물며 먹고 마시며 거기서 유숙하다가',7029),
('jdg-19-5','jdg','사사기',19,5,'넷째 날 아침에 일찍이 일어나 떠나고자 하매 그 여자의 아버지가 그의 사위에게 이르되 떡을 조금 먹고 그대의 기력을 돋운 후에 그대의 길을 가라 하니라',7030),
('jdg-19-6','jdg','사사기',19,6,'두 사람이 앉아서 함께 먹고 마시매 그 여자의 아버지가 그 사람에게 이르되 청하노니 이 밤을 여기서 유숙하여 그대의 마음을 즐겁게 하라 하니',7031),
('jdg-19-7','jdg','사사기',19,7,'그 사람이 일어나서 가고자 하되 그의 장인의 간청으로 거기서 다시 유숙하더니',7032),
('jdg-19-8','jdg','사사기',19,8,'다섯째 날 아침에 일찍이 일어나 떠나고자 하매 그 여자의 아버지가 이르되 청하노니 그대의 기력을 돋우고 해가 기울도록 머물라 하므로 두 사람이 함께 먹고',7033),
('jdg-19-9','jdg','사사기',19,9,'그 사람이 첩과 하인과 더불어 일어나 떠나고자 하매 그의 장인 곧 그 여자의 아버지가 그에게 이르되 보라 이제 날이 저물어 가니 청하건대 이 밤도 유숙하라 보라 해가 기울었느니라 그대는 여기서 유숙하여 그대의 마음을 즐겁게 하고 내일 일찍이 그대의 길을 가서 그대의 집으로 돌아가라 하니',7034),
('jdg-19-10','jdg','사사기',19,10,'그 사람이 다시 밤을 지내고자 하지 아니하여 일어나서 떠나 여부스 맞은편에 이르렀으니 여부스는 곧 예루살렘이라 안장 지운 나귀 두 마리와 첩이 그와 함께 하였더라',7035),
('jdg-19-11','jdg','사사기',19,11,'그들이 여부스에 가까이 갔을 때에 해가 지려 하는지라 종이 주인에게 이르되 청하건대 우리가 돌이켜 여부스 사람의 이 성읍에 들어가서 유숙하십시다 하니',7036),
('jdg-19-12','jdg','사사기',19,12,'주인이 그에게 이르되 우리가 돌이켜 이스라엘 자손에게 속하지 아니한 이방 사람의 성읍으로 들어갈 것이 아니니 기브아로 나아가리라 하고',7037),
('jdg-19-13','jdg','사사기',19,13,'또 그 종에게 이르되 우리가 기브아나 라마 중 한 곳에 가서 거기서 유숙하자 하고',7038),
('jdg-19-14','jdg','사사기',19,14,'모두 앞으로 나아가더니 베냐민에 속한 기브아에 가까이 이르러 해가 진지라',7039),
('jdg-19-15','jdg','사사기',19,15,'기브아에 가서 유숙하려고 그리로 돌아 들어가서 성읍 넓은 거리에 앉아 있으나 그를 집으로 영접하여 유숙하게 하는 자가 없었더라',7040),
('jdg-19-16','jdg','사사기',19,16,'저녁 때에 한 노인이 밭에서 일하다가 돌아오니 그 사람은 본래 에브라임 산지 사람으로서 기브아에 거류하는 자요 그 곳 사람들은 베냐민 자손이더라',7041),
('jdg-19-17','jdg','사사기',19,17,'노인이 눈을 들어 성읍 넓은 거리에 나그네가 있는 것을 본지라 노인이 묻되 그대는 어디로 가며 어디서 왔느냐 하니',7042),
('jdg-19-18','jdg','사사기',19,18,'그가 그에게 이르되 우리는 유다 베들레헴에서 에브라임 산지 구석으로 가나이다 나는 그 곳 사람으로서 유다 베들레헴에 갔다가 이제 여호와의 집으로 가는 중인데 나를 자기 집으로 영접하는 사람이 없나이다',7043),
('jdg-19-19','jdg','사사기',19,19,'우리에게는 나귀들에게 먹일 짚과 여물이 있고 나와 당신의 여종과 당신의 종인 우리들과 함께 한 청년에게 먹을 양식과 포도주가 있어 무엇이든지 부족함이 없나이다 하는지라',7044),
('jdg-19-20','jdg','사사기',19,20,'그 노인이 이르되 그대는 안심하라 그대의 쓸 것은 모두 내가 담당할 것이니 거리에서는 유숙하지 말라 하고',7045),
('jdg-19-21','jdg','사사기',19,21,'그를 데리고 자기 집에 들어가서 나귀에게 먹이니 그들이 발을 씻고 먹고 마시니라',7046),
('jdg-19-22','jdg','사사기',19,22,'그들이 마음을 즐겁게 할 때에 그 성읍의 불량배들이 그 집을 에워싸고 문을 두들기며 집 주인 노인에게 말하여 이르되 네 집에 들어온 사람을 끌어내라 우리가 그와 관계하리라 하니',7047),
('jdg-19-23','jdg','사사기',19,23,'집 주인 그 사람이 그들에게로 나와서 이르되 아니라 내 형제들아 청하노니 이같은 악행을 저지르지 말라 이 사람이 내 집에 들어왔으니 이런 망령된 일을 행하지 말라',7048),
('jdg-19-24','jdg','사사기',19,24,'보라 여기 내 처녀 딸과 이 사람의 첩이 있은즉 내가 그들을 끌어내리니 너희가 그들을 욕보이든지 너희 눈에 좋은 대로 행하되 오직 이 사람에게는 이런 망령된 일을 행하지 말라 하나',7049),
('jdg-19-25','jdg','사사기',19,25,'무리가 듣지 아니하므로 그 사람이 자기 첩을 붙잡아 그들에게 밖으로 끌어내매 그들이 그 여자와 관계하였고 밤새도록 그 여자를 능욕하다가 새벽 미명에 놓은지라',7050),
('jdg-19-26','jdg','사사기',19,26,'동틀 때에 여인이 자기의 주인이 있는 그 사람의 집 문에 이르러 엎드러져 밝기까지 거기 엎드러져 있더라',7051),
('jdg-19-27','jdg','사사기',19,27,'그의 주인이 일찍이 일어나 집 문을 열고 떠나고자 하더니 그 여인이 집 문에 엎드러져 있고 그의 두 손이 문지방에 있는 것을 보고',7052),
('jdg-19-28','jdg','사사기',19,28,'그에게 이르되 일어나라 우리가 떠나가자 하나 아무 대답이 없는지라 이에 그의 시체를 나귀에 싣고 행하여 자기 곳에 돌아가서',7053),
('jdg-19-29','jdg','사사기',19,29,'그 집에 이르러서는 칼을 가지고 자기 첩의 시체를 거두어 그 마디를 찍어 열두 덩이에 나누고 그것을 이스라엘 사방에 두루 보내매',7054),
('jdg-19-30','jdg','사사기',19,30,'그것을 보는 자가 다 이르되 이스라엘 자손이 애굽 땅에서 올라온 날부터 오늘까지 이런 일은 일어나지도 아니하였고 보지도 못하였도다 이 일을 생각하고 상의한 후에 말하자 하니라',7055),
('jdg-20-1','jdg','사사기',20,1,'이에 모든 이스라엘 자손이 단에서부터 브엘세바까지와 길르앗 땅에서 나와서 그 회중이 일제히 미스바에서 여호와 앞에 모였으니',7056),
('jdg-20-2','jdg','사사기',20,2,'온 백성의 어른 곧 이스라엘 모든 지파의 어른들은 하나님 백성의 총회에 섰고 칼을 빼는 보병은 사십만 명이었으며',7057),
('jdg-20-3','jdg','사사기',20,3,'이스라엘 자손이 미스바에 올라간 것을 베냐민 자손이 들었더라 이스라엘 자손이 이르되 이 악한 일이 어떻게 일어났는지 우리에게 말하라 하니',7058),
('jdg-20-4','jdg','사사기',20,4,'레위 사람 곧 죽임을 당한 여인의 남편이 대답하여 이르되 내가 내 첩과 더불어 베냐민에 속한 기브아에 유숙하러 갔더니',7059),
('jdg-20-5','jdg','사사기',20,5,'기브아 사람들이 나를 치러 일어나서 밤에 내가 묵고 있던 집을 에워싸고 나를 죽이려 하고 내 첩을 욕보여 그를 죽게 한지라',7060),
('jdg-20-6','jdg','사사기',20,6,'내가 내 첩의 시체를 거두어 쪼개서 이스라엘 기업의 온 땅에 보냈나니 이는 그들이 이스라엘 중에서 음행과 망령된 일을 행하였기 때문이라',7061),
('jdg-20-7','jdg','사사기',20,7,'이스라엘 자손들아 너희가 다 여기 있은즉 너희의 의견과 방책을 낼지니라 하니라',7062),
('jdg-20-8','jdg','사사기',20,8,'모든 백성이 일제히 일어나 이르되 우리가 한 사람도 자기 장막으로 돌아가지 말며 한 사람도 자기 집으로 들어가지 말고',7063),
('jdg-20-9','jdg','사사기',20,9,'우리가 이제 기브아 사람에게 이렇게 행하리니 곧 제비를 뽑아서 그들을 치되',7064),
('jdg-20-10','jdg','사사기',20,10,'우리가 이스라엘 모든 지파 중에서 백 명에 열 명, 천 명에 백 명, 만 명에 천 명을 뽑아 그 백성을 위하여 양식을 준비하고 그들에게 베냐민의 기브아에 가서 그 무리가 이스라엘 중에서 망령된 일을 행한 대로 징계하게 하리라 하니라',7065),
('jdg-20-11','jdg','사사기',20,11,'이와 같이 이스라엘 모든 사람이 하나 같이 합심하여 그 성읍을 치려고 모였더라',7066),
('jdg-20-12','jdg','사사기',20,12,'이스라엘 지파들이 베냐민 온 지파에 사람들을 보내어 두루 다니며 이르기를 너희 중에서 생긴 이 악행이 어찌 됨이냐',7067),
('jdg-20-13','jdg','사사기',20,13,'그런즉 이제 기브아 사람들 곧 그 불량배들을 우리에게 넘겨 주어서 우리가 그들을 죽여 이스라엘 중에서 악을 제거하여 버리게 하라 하나 베냐민 자손이 그들의 형제 이스라엘 자손의 말을 듣지 아니하고',7068),
('jdg-20-14','jdg','사사기',20,14,'도리어 성읍들로부터 기브아에 모이고 나가서 이스라엘 자손과 싸우고자 하니라',7069),
('jdg-20-15','jdg','사사기',20,15,'그 때에 그 성읍들로부터 나온 베냐민 자손의 수는 칼을 빼는 자가 모두 이만 육천 명이요 그 외에 기브아 주민 중 택한 자가 칠백 명인데',7070),
('jdg-20-16','jdg','사사기',20,16,'이 모든 백성 중에서 택한 칠백 명은 다 왼손잡이라 물매로 돌을 던지면 조금도 틀림이 없는 자들이더라',7071),
('jdg-20-17','jdg','사사기',20,17,'베냐민 자손 외에 이스라엘 사람으로서 칼을 빼는 자의 수는 사십만 명이니 다 전사라',7072),
('jdg-20-18','jdg','사사기',20,18,'이스라엘 자손이 일어나 벧엘에 올라가서 하나님께 여쭈어 이르되 우리 중에 누가 먼저 올라가서 베냐민 자손과 싸우리이까 하니 여호와께서 말씀하시되 유다가 먼저 갈지니라 하시니라',7073),
('jdg-20-19','jdg','사사기',20,19,'이스라엘 자손이 아침에 일어나 기브아를 대하여 진을 치니라',7074),
('jdg-20-20','jdg','사사기',20,20,'이스라엘 사람이 나가 베냐민과 싸우려고 전열을 갖추고 기브아에서 그들과 싸우고자 하매',7075),
('jdg-20-21','jdg','사사기',20,21,'베냐민 자손이 기브아에서 나와서 당일에 이스라엘 사람 이만 이천 명을 땅에 엎드러뜨렸으나',7076),
('jdg-20-22','jdg','사사기',20,22,'이스라엘 사람들이 스스로 용기를 내어 첫날 전열을 갖추었던 곳에서 다시 전열을 갖추니라',7077),
('jdg-20-23','jdg','사사기',20,23,'이스라엘 자손이 올라가 여호와 앞에서 저물도록 울며 여호와께 여쭈어 이르되 내가 다시 나아가서 내 형제 베냐민 자손과 싸우리이까 하니 여호와께서 말씀하시되 올라가서 치라 하시니라',7078),
('jdg-20-24','jdg','사사기',20,24,'그 이튿날에 이스라엘 자손이 베냐민 자손을 치러 나아가매',7079),
('jdg-20-25','jdg','사사기',20,25,'베냐민도 그 이튿날에 기브아에서 그들을 치러 나와서 다시 이스라엘 자손 만 팔천 명을 땅에 엎드러뜨렸으니 다 칼을 빼는 자였더라',7080),
('jdg-20-26','jdg','사사기',20,26,'이에 온 이스라엘 자손 모든 백성이 올라가 벧엘에 이르러 울며 거기서 여호와 앞에 앉아서 그 날이 저물도록 금식하고 번제와 화목제를 여호와 앞에 드리고',7081),
('jdg-20-27','jdg','사사기',20,27,'이스라엘 자손이 여호와께 물으니라 그 때에는 하나님의 언약궤가 거기 있고',7082),
('jdg-20-28','jdg','사사기',20,28,'아론의 손자인 엘르아살의 아들 비느하스가 그 앞에 모시고 섰더라 이스라엘 자손들이 여쭈기를 우리가 다시 나아가 내 형제 베냐민 자손과 싸우리이까 말리이까 하니 여호와께서 이르시되 올라가라 내일은 내가 그를 네 손에 넘겨 주리라 하시는지라',7083),
('jdg-20-29','jdg','사사기',20,29,'이스라엘이 기브아 주위에 군사를 매복하니라',7084),
('jdg-20-30','jdg','사사기',20,30,'이스라엘 자손이 셋째 날에 베냐민 자손을 치러 올라가서 전과 같이 기브아에 맞서 전열을 갖추매',7085),
('jdg-20-31','jdg','사사기',20,31,'베냐민 자손이 나와서 백성을 맞더니 꾀임에 빠져 성읍을 떠났더라 그들이 큰 길 곧 한쪽은 벧엘로 올라가는 길이요 한쪽은 기브아의 들로 가는 길에서 백성을 쳐서 전과 같이 이스라엘 사람 삼십 명 가량을 죽이기 시작하며',7086),
('jdg-20-32','jdg','사사기',20,32,'베냐민 자손이 스스로 이르기를 이들이 처음과 같이 우리 앞에서 패한다 하나 이스라엘 자손은 이르기를 우리가 도망하여 그들을 성읍에서 큰 길로 꾀어내자 하고',7087),
('jdg-20-33','jdg','사사기',20,33,'이스라엘 사람이 모두 그들의 처소에서 일어나서 바알다말에서 전열을 갖추었고 이스라엘의 복병은 그 장소 곧 기브아 초장에서 쏟아져 나왔더라',7088),
('jdg-20-34','jdg','사사기',20,34,'온 이스라엘 사람 중에서 택한 사람 만 명이 기브아에 이르러 치매 싸움이 치열하나 베냐민 사람은 화가 자기에게 미친 줄을 알지 못하였더라',7089),
('jdg-20-35','jdg','사사기',20,35,'여호와께서 이스라엘 앞에서 베냐민을 치시매 당일에 이스라엘 자손이 베냐민 사람 이만 오천백 명을 죽였으니 다 칼을 빼는 자였더라',7090),
('jdg-20-36','jdg','사사기',20,36,'이에 베냐민 자손이 자기가 패한 것을 깨달았으니 이는 이스라엘 사람이 기브아에 매복한 군사를 믿고 잠깐 베냐민 사람 앞을 피하매',7091),
('jdg-20-37','jdg','사사기',20,37,'복병이 급히 나와 기브아로 돌격하고 나아가며 칼날로 온 성읍을 쳤음이더라',7092),
('jdg-20-38','jdg','사사기',20,38,'처음에 이스라엘 사람과 복병 사이에 약속하기를 성읍에서 큰 연기가 치솟는 것으로 군호를 삼자 하고',7093),
('jdg-20-39','jdg','사사기',20,39,'이스라엘 사람은 싸우다가 물러가고 베냐민 사람은 이스라엘 사람 삼십 명 가량을 쳐죽이기를 시작하며 이르기를 이들이 틀림없이 처음 싸움 같이 우리에게 패한다 하다가',7094),
('jdg-20-40','jdg','사사기',20,40,'연기 구름이 기둥 같이 성읍 가운데에서 치솟을 때에 베냐민 사람이 뒤를 돌아보매 온 성읍에 연기가 하늘에 닿았고',7095),
('jdg-20-41','jdg','사사기',20,41,'이스라엘 사람은 돌아서는지라 베냐민 사람들이 화가 자기들에게 미친 것을 보고 심히 놀라',7096),
('jdg-20-42','jdg','사사기',20,42,'이스라엘 사람 앞에서 몸을 돌려 광야 길로 향하였으나 군사가 급히 추격하며 각 성읍에서 나온 자를 그 가운데에서 진멸하니라',7097),
('jdg-20-43','jdg','사사기',20,43,'그들이 베냐민 사람을 에워싸고 기브아 앞 동쪽까지 추격하며 그 쉬는 곳에서 짓밟으매',7098),
('jdg-20-44','jdg','사사기',20,44,'베냐민 중에서 엎드러진 자가 만 팔천 명이니 다 용사더라',7099),
('jdg-20-45','jdg','사사기',20,45,'그들이 몸을 돌려 광야로 도망하였으나 림몬 바위에 이르는 큰 길에서 이스라엘이 또 오천 명을 이삭 줍듯 하고 또 급히 그 뒤를 따라 기돔에 이르러 또 이천 명을 죽였으니',7100),
('jdg-20-46','jdg','사사기',20,46,'이 날에 베냐민 사람으로서 칼을 빼는 자가 엎드러진 것이 모두 이만 오천 명이니 다 용사였더라',7101),
('jdg-20-47','jdg','사사기',20,47,'베냐민 사람 육백 명이 돌이켜 광야로 도망하여 림몬 바위에 이르러 거기에서 넉 달 동안을 지냈더라',7102),
('jdg-20-48','jdg','사사기',20,48,'이스라엘 사람이 베냐민 자손에게로 돌아와서 온 성읍과 가축과 만나는 자를 다 칼날로 치고 닥치는 성읍은 모두 다 불살랐더라',7103),
('jdg-21-1','jdg','사사기',21,1,'이스라엘 사람들이 미스바에서 맹세하여 이르기를 우리 중에 누구든지 딸을 베냐민 사람에게 아내로 주지 아니하리라 하였더라',7104),
('jdg-21-2','jdg','사사기',21,2,'백성이 벧엘에 이르러 거기서 저녁까지 하나님 앞에 앉아서 큰 소리로 울며',7105),
('jdg-21-3','jdg','사사기',21,3,'이르되 이스라엘의 하나님 여호와여 어찌하여 이스라엘에 이런 일이 생겨서 오늘 이스라엘 중에 한 지파가 없어지게 하시나이까 하더니',7106),
('jdg-21-4','jdg','사사기',21,4,'이튿날에 백성이 일찍이 일어나 거기에 한 제단을 쌓고 번제와 화목제를 드렸더라',7107),
('jdg-21-5','jdg','사사기',21,5,'이스라엘 자손이 이르되 이스라엘 온 지파 중에 총회와 함께 하여 여호와 앞에 올라오지 아니한 자가 누구냐 하니 이는 그들이 크게 맹세하기를 미스바에 와서 여호와 앞에 이르지 아니하는 자는 반드시 죽일 것이라 하였음이라',7108),
('jdg-21-6','jdg','사사기',21,6,'이스라엘 자손이 그들의 형제 베냐민을 위하여 뉘우쳐 이르되 오늘 이스라엘 중에 한 지파가 끊어졌도다',7109),
('jdg-21-7','jdg','사사기',21,7,'그 남은 자들에게 우리가 어떻게 하면 아내를 얻게 하리요 우리가 전에 여호와로 맹세하여 우리의 딸을 그들의 아내로 주지 아니하리라 하였도다',7110),
('jdg-21-8','jdg','사사기',21,8,'또 이르되 이스라엘 지파 중 미스바에 올라와서 여호와께 이르지 아니한 자가 누구냐 하고 본즉 야베스 길르앗에서는 한 사람도 진영에 이르러 총회에 참여하지 아니하였으니',7111),
('jdg-21-9','jdg','사사기',21,9,'백성을 계수할 때에 야베스 길르앗 주민이 하나도 거기 없음을 보았음이라',7112),
('jdg-21-10','jdg','사사기',21,10,'회중이 큰 용사 만 이천 명을 그리로 보내며 그들에게 명령하여 이르되 가서 야베스 길르앗 주민과 부녀와 어린 아이를 칼날로 치라',7113),
('jdg-21-11','jdg','사사기',21,11,'너희가 행할 일은 모든 남자 및 남자와 잔 여자를 진멸하여 바칠 것이니라 하였더라',7114),
('jdg-21-12','jdg','사사기',21,12,'그들이 야베스 길르앗 주민 중에서 젊은 처녀 사백 명을 얻었으니 이는 아직 남자와 동침한 일이 없어 남자를 알지 못하는 자라 그들을 실로 진영으로 데려오니 이 곳은 가나안 땅이더라',7115),
('jdg-21-13','jdg','사사기',21,13,'온 회중이 림몬 바위에 있는 베냐민 자손에게 사람을 보내어 평화를 공포하게 하였더니',7116),
('jdg-21-14','jdg','사사기',21,14,'그 때에 베냐민이 돌아온지라 이에 이스라엘 사람이 야베스 길르앗 여자들 중에서 살려 둔 여자들을 그들에게 주었으나 아직도 부족하므로',7117),
('jdg-21-15','jdg','사사기',21,15,'백성들이 베냐민을 위하여 뉘우쳤으니 이는 여호와께서 이스라엘 지파들 중에 한 지파가 빠지게 하셨음이었더라',7118),
('jdg-21-16','jdg','사사기',21,16,'회중의 장로들이 이르되 베냐민의 여인이 다 멸절되었으니 이제 그 남은 자들에게 어떻게 하여야 아내를 얻게 할까 하고',7119),
('jdg-21-17','jdg','사사기',21,17,'또 이르되 베냐민 중 도망하여 살아 남은 자에게 마땅히 기업이 있어야 하리니 그리하면 이스라엘 중에 한 지파가 사라짐이 없으리라',7120),
('jdg-21-18','jdg','사사기',21,18,'그러나 우리가 우리의 딸을 그들의 아내로 주지 못하리니 이는 이스라엘 자손이 맹세하여 이르기를 딸을 베냐민에게 아내로 주는 자는 저주를 받으리라 하였음이로다 하니라',7121),
('jdg-21-19','jdg','사사기',21,19,'또 이르되 보라 벧엘 북쪽 르보나 남쪽 벧엘에서 세겜으로 올라가는 큰 길 동쪽 실로에 매년 여호와의 명절이 있도다 하고',7122),
('jdg-21-20','jdg','사사기',21,20,'베냐민 자손에게 명령하여 이르되 가서 포도원에 숨어',7123),
('jdg-21-21','jdg','사사기',21,21,'보다가 실로의 여자들이 춤을 추러 나오거든 너희는 포도원에서 나와서 실로의 딸 중에서 각각 하나를 붙들어 가지고 자기의 아내로 삼아 베냐민 땅으로 돌아가라',7124),
('jdg-21-22','jdg','사사기',21,22,'만일 그의 아버지나 형제가 와서 우리에게 시비하면 우리가 그에게 말하기를 청하건대 너희는 우리에게 은혜를 베풀어 그들을 우리에게 줄지니라 이는 우리가 전쟁할 때에 각 사람을 위하여 그의 아내를 얻어 주지 못하였고 너희가 자의로 그들에게 준 것이 아니니 너희에게 죄가 없을 것임이니라 하겠노라 하매',7125),
('jdg-21-23','jdg','사사기',21,23,'베냐민 자손이 그같이 행하여 춤추는 여자들 중에서 자기들의 숫자대로 붙들어 아내로 삼아 자기 기업에 돌아가서 성읍들을 건축하고 거기에 거주하였더라',7126),
('jdg-21-24','jdg','사사기',21,24,'그 때에 이스라엘 자손이 그 곳에서 각기 자기의 지파, 자기의 가족에게로 돌아갔으니 곧 각기 그 곳에서 나와서 자기의 기업으로 돌아갔더라',7127),
('jdg-21-25','jdg','사사기',21,25,'그 때에 이스라엘에 왕이 없으므로 사람이 각기 자기의 소견에 옳은 대로 행하였더라␀␀␀␀␀␀␀',7128),
('rut-1-1','rut','룻기',1,1,'사사들이 치리하던 때에 그 땅에 흉년이 드니라 유다 베들레헴에 한 사람이 그의 아내와 두 아들을 데리고 모압 지방에 가서 거류하였는데',7129),
('rut-1-2','rut','룻기',1,2,'그 사람의 이름은 엘리멜렉이요 그의 아내의 이름은 나오미요 그의 두 아들의 이름은 말론과 기룐이니 유다 베들레헴 에브랏 사람들이더라 그들이 모압 지방에 들어가서 거기 살더니',7130),
('rut-1-3','rut','룻기',1,3,'나오미의 남편 엘리멜렉이 죽고 나오미와 그의 두 아들이 남았으며',7131),
('rut-1-4','rut','룻기',1,4,'그들은 모압 여자 중에서 그들의 아내를 맞이하였는데 하나의 이름은 오르바요 하나의 이름은 룻이더라 그들이 거기에 거주한 지 십 년쯤에',7132),
('rut-1-5','rut','룻기',1,5,'말론과 기룐 두 사람이 다 죽고 그 여인은 두 아들과 남편의 뒤에 남았더라',7133),
('rut-1-6','rut','룻기',1,6,'그 여인이 모압 지방에서 여호와께서 자기 백성을 돌보시사 그들에게 양식을 주셨다 함을 듣고 이에 두 며느리와 함께 일어나 모압 지방에서 돌아오려 하여',7134),
('rut-1-7','rut','룻기',1,7,'있던 곳에서 나오고 두 며느리도 그와 함께 하여 유다 땅으로 돌아오려고 길을 가다가',7135),
('rut-1-8','rut','룻기',1,8,'나오미가 두 며느리에게 이르되 너희는 각기 너희 어머니의 집으로 돌아가라 너희가 죽은 자들과 나를 선대한 것 같이 여호와께서 너희를 선대하시기를 원하며',7136),
('rut-1-9','rut','룻기',1,9,'여호와께서 너희에게 허락하사 각기 남편의 집에서 위로를 받게 하시기를 원하노라 하고 그들에게 입 맞추매 그들이 소리를 높여 울며',7137),
('rut-1-10','rut','룻기',1,10,'나오미에게 이르되 아니니이다 우리는 어머니와 함께 어머니의 백성에게로 돌아가겠나이다 하는지라',7138),
('rut-1-11','rut','룻기',1,11,'나오미가 이르되 내 딸들아 돌아가라 너희가 어찌 나와 함께 가려느냐 내 태중에 너희의 남편 될 아들들이 아직 있느냐',7139),
('rut-1-12','rut','룻기',1,12,'내 딸들아 되돌아 가라 나는 늙었으니 남편을 두지 못할지라 가령 내가 소망이 있다고 말한다든지 오늘 밤에 남편을 두어 아들들을 낳는다 하더라도',7140),
('rut-1-13','rut','룻기',1,13,'너희가 어찌 그들이 자라기를 기다리겠으며 어찌 남편 없이 지내겠다고 결심하겠느냐 내 딸들아 그렇지 아니하니라 여호와의 손이 나를 치셨으므로 나는 너희로 말미암아 더욱 마음이 아프도다 하매',7141),
('rut-1-14','rut','룻기',1,14,'그들이 소리를 높여 다시 울더니 오르바는 그의 시어머니에게 입 맞추되 룻은 그를 붙좇았더라',7142),
('rut-1-15','rut','룻기',1,15,'나오미가 또 이르되 보라 네 동서는 그의 백성과 그의 신들에게로 돌아가나니 너도 너의 동서를 따라 돌아가라 하니',7143),
('rut-1-16','rut','룻기',1,16,'룻이 이르되 내게 어머니를 떠나며 어머니를 따르지 말고 돌아가라 강권하지 마옵소서 어머니께서 가시는 곳에 나도 가고 어머니께서 머무시는 곳에서 나도 머물겠나이다 어머니의 백성이 나의 백성이 되고 어머니의 하나님이 나의 하나님이 되시리니',7144),
('rut-1-17','rut','룻기',1,17,'어머니께서 죽으시는 곳에서 나도 죽어 거기 묻힐 것이라 만일 내가 죽는 일 외에 어머니를 떠나면 여호와께서 내게 벌을 내리시고 더 내리시기를 원하나이다 하는지라',7145),
('rut-1-18','rut','룻기',1,18,'나오미가 룻이 자기와 함께 가기로 굳게 결심함을 보고 그에게 말하기를 그치니라',7146),
('rut-1-19','rut','룻기',1,19,'이에 그 두 사람이 베들레헴까지 갔더라 베들레헴에 이를 때에 온 성읍이 그들로 말미암아 떠들며 이르기를 이이가 나오미냐 하는지라',7147),
('rut-1-20','rut','룻기',1,20,'나오미가 그들에게 이르되 나를 나오미라 부르지 말고 나를 마라라 부르라 이는 전능자가 나를 심히 괴롭게 하셨음이니라',7148),
('rut-1-21','rut','룻기',1,21,'내가 풍족하게 나갔더니 여호와께서 내게 비어 돌아오게 하셨느니라 여호와께서 나를 징벌하셨고 전능자가 나를 괴롭게 하셨거늘 너희가 어찌 나를 나오미라 부르느냐 하니라',7149),
('rut-1-22','rut','룻기',1,22,'나오미가 모압 지방에서 그의 며느리 모압 여인 룻과 함께 돌아왔는데 그들이 보리 추수 시작할 때에 베들레헴에 이르렀더라',7150),
('rut-2-1','rut','룻기',2,1,'나오미의 남편 엘리멜렉의 친족으로 유력한 자가 있으니 그의 이름은 보아스더라',7151),
('rut-2-2','rut','룻기',2,2,'모압 여인 룻이 나오미에게 이르되 원하건대 내가 밭으로 가서 내가 누구에게 은혜를 입으면 그를 따라서 이삭을 줍겠나이다 하니 나오미가 그에게 이르되 내 딸아 갈지어다 하매',7152),
('rut-2-3','rut','룻기',2,3,'룻이 가서 베는 자를 따라 밭에서 이삭을 줍는데 우연히 엘리멜렉의 친족 보아스에게 속한 밭에 이르렀더라',7153),
('rut-2-4','rut','룻기',2,4,'마침 보아스가 베들레헴에서부터 와서 베는 자들에게 이르되 여호와께서 너희와 함께 하시기를 원하노라 하니 그들이 대답하되 여호와께서 당신에게 복 주시기를 원하나이다 하니라',7154),
('rut-2-5','rut','룻기',2,5,'보아스가 베는 자들을 거느린 사환에게 이르되 이는 누구의 소녀냐 하니',7155),
('rut-2-6','rut','룻기',2,6,'베는 자를 거느린 사환이 대답하여 이르되 이는 나오미와 함께 모압 지방에서 돌아온 모압 소녀인데',7156),
('rut-2-7','rut','룻기',2,7,'그의 말이 나로 베는 자를 따라 단 사이에서 이삭을 줍게 하소서 하였고 아침부터 와서는 잠시 집에서 쉰 외에 지금까지 계속하는 중이니이다',7157),
('rut-2-8','rut','룻기',2,8,'보아스가 룻에게 이르되 내 딸아 들으라 이삭을 주우러 다른 밭으로 가지 말며 여기서 떠나지 말고 나의 소녀들과 함께 있으라',7158),
('rut-2-9','rut','룻기',2,9,'그들이 베는 밭을 보고 그들을 따르라 내가 그 소년들에게 명령하여 너를 건드리지 말라 하였느니라 목이 마르거든 그릇에 가서 소년들이 길어 온 것을 마실지니라 하는지라',7159),
('rut-2-10','rut','룻기',2,10,'룻이 엎드려 얼굴을 땅에 대고 절하며 그에게 이르되 나는 이방 여인이거늘 당신이 어찌하여 내게 은혜를 베푸시며 나를 돌보시나이까 하니',7160),
('rut-2-11','rut','룻기',2,11,'보아스가 그에게 대답하여 이르되 네 남편이 죽은 후로 네가 시어머니에게 행한 모든 것과 네 부모와 고국을 떠나 전에 알지 못하던 백성에게로 온 일이 내게 분명히 알려졌느니라',7161),
('rut-2-12','rut','룻기',2,12,'여호와께서 네가 행한 일에 보답하시기를 원하며 이스라엘의 하나님 여호와께서 그의 날개 아래에 보호를 받으러 온 네게 온전한 상 주시기를 원하노라 하는지라',7162),
('rut-2-13','rut','룻기',2,13,'룻이 이르되 내 주여 내가 당신께 은혜 입기를 원하나이다 나는 당신의 하녀 중의 하나와도 같지 못하오나 당신이 이 하녀를 위로하시고 마음을 기쁘게 하는 말씀을 하셨나이다 하니라',7163),
('rut-2-14','rut','룻기',2,14,'식사할 때에 보아스가 룻에게 이르되 이리로 와서 떡을 먹으며 네 떡 조각을 초에 찍으라 하므로 룻이 곡식 베는 자 곁에 앉으니 그가 볶은 곡식을 주매 룻이 배불리 먹고 남았더라',7164),
('rut-2-15','rut','룻기',2,15,'룻이 이삭을 주우러 일어날 때에 보아스가 자기 소년들에게 명령하여 이르되 그에게 곡식 단 사이에서 줍게 하고 책망하지 말며',7165),
('rut-2-16','rut','룻기',2,16,'또 그를 위하여 곡식 다발에서 조금씩 뽑아 버려서 그에게 줍게 하고 꾸짖지 말라 하니라',7166),
('rut-2-17','rut','룻기',2,17,'룻이 밭에서 저녁까지 줍고 그 주운 것을 떠니 보리가 한 에바쯤 되는지라',7167),
('rut-2-18','rut','룻기',2,18,'그것을 가지고 성읍에 들어가서 시어머니에게 그 주운 것을 보이고 그가 배불리 먹고 남긴 것을 내어 시어머니에게 드리매',7168),
('rut-2-19','rut','룻기',2,19,'시어머니가 그에게 이르되 오늘 어디서 주웠느냐 어디서 일을 하였느냐 너를 돌본 자에게 복이 있기를 원하노라 하니 룻이 누구에게서 일했는지를 시어머니에게 알게 하여 이르되 오늘 일하게 한 사람의 이름은 보아스니이다 하는지라',7169),
('rut-2-20','rut','룻기',2,20,'나오미가 자기 며느리에게 이르되 그가 여호와로부터 복 받기를 원하노라 그가 살아 있는 자와 죽은 자에게 은혜 베풀기를 그치지 아니하도다 하고 나오미가 또 그에게 이르되 그 사람은 우리와 가까우니 우리 기업을 무를 자 중의 하나이니라 하니라',7170),
('rut-2-21','rut','룻기',2,21,'모압 여인 룻이 이르되 그가 내게 또 이르기를 내 추수를 다 마치기까지 너는 내 소년들에게 가까이 있으라 하더이다 하니',7171),
('rut-2-22','rut','룻기',2,22,'나오미가 며느리 룻에게 이르되 내 딸아 너는 그의 소녀들과 함께 나가고 다른 밭에서 사람을 만나지 아니하는 것이 좋으니라 하는지라',7172),
('rut-2-23','rut','룻기',2,23,'이에 룻이 보아스의 소녀들에게 가까이 있어서 보리 추수와 밀 추수를 마치기까지 이삭을 주우며 그의 시어머니와 함께 거주하니라',7173),
('rut-3-1','rut','룻기',3,1,'룻의 시어머니 나오미가 그에게 이르되 내 딸아 내가 너를 위하여 안식할 곳을 구하여 너를 복되게 하여야 하지 않겠느냐',7174),
('rut-3-2','rut','룻기',3,2,'네가 함께 하던 하녀들을 둔 보아스는 우리의 친족이 아니냐 보라 그가 오늘 밤에 타작 마당에서 보리를 까불리라',7175),
('rut-3-3','rut','룻기',3,3,'그런즉 너는 목욕하고 기름을 바르고 의복을 입고 타작 마당에 내려가서 그 사람이 먹고 마시기를 다 하기까지는 그에게 보이지 말고',7176),
('rut-3-4','rut','룻기',3,4,'그가 누울 때에 너는 그가 눕는 곳을 알았다가 들어가서 그의 발치 이불을 들고 거기 누우라 그가 네 할 일을 네게 알게 하리라 하니',7177),
('rut-3-5','rut','룻기',3,5,'룻이 시어머니에게 이르되 어머니의 말씀대로 내가 다 행하리이다 하니라',7178),
('rut-3-6','rut','룻기',3,6,'그가 타작 마당으로 내려가서 시어머니의 명령대로 다 하니라',7179),
('rut-3-7','rut','룻기',3,7,'보아스가 먹고 마시고 마음이 즐거워 가서 곡식 단 더미의 끝에 눕는지라 룻이 가만히 가서 그의 발치 이불을 들고 거기 누웠더라',7180),
('rut-3-8','rut','룻기',3,8,'밤중에 그가 놀라 몸을 돌이켜 본즉 한 여인이 자기 발치에 누워 있는지라',7181),
('rut-3-9','rut','룻기',3,9,'이르되 네가 누구냐 하니 대답하되 나는 당신의 여종 룻이오니 당신의 옷자락을 펴 당신의 여종을 덮으소서 이는 당신이 기업을 무를 자가 됨이니이다 하니',7182),
('rut-3-10','rut','룻기',3,10,'그가 이르되 내 딸아 여호와께서 네게 복 주시기를 원하노라 네가 가난하건 부하건 젊은 자를 따르지 아니하였으니 네가 베푼 인애가 처음보다 나중이 더하도다',7183),
('rut-3-11','rut','룻기',3,11,'그리고 이제 내 딸아 두려워하지 말라 내가 네 말대로 네게 다 행하리라 네가 현숙한 여자인 줄을 나의 성읍 백성이 다 아느니라',7184),
('rut-3-12','rut','룻기',3,12,'참으로 나는 기업을 무를 자이나 기업 무를 자로서 나보다 더 가까운 사람이 있으니',7185),
('rut-3-13','rut','룻기',3,13,'이 밤에 여기서 머무르라 아침에 그가 기업 무를 자의 책임을 네게 이행하려 하면 좋으니 그가 그 기업 무를 자의 책임을 행할 것이니라 만일 그가 기업 무를 자의 책임을 네게 이행하기를 기뻐하지 아니하면 여호와께서 살아 계심을 두고 맹세하노니 내가 기업 무를 자의 책임을 네게 이행하리라 아침까지 누워 있을지니라 하는지라',7186),
('rut-3-14','rut','룻기',3,14,'룻이 새벽까지 그의 발치에 누웠다가 사람이 서로 알아보기 어려울 때에 일어났으니 보아스가 말하기를 여인이 타작 마당에 들어온 것을 사람이 알지 못하여야 할 것이라 하였음이라',7187),
('rut-3-15','rut','룻기',3,15,'보아스가 이르되 네 겉옷을 가져다가 그것을 펴서 잡으라 하매 그것을 펴서 잡으니 보리를 여섯 번 되어 룻에게 지워 주고 성읍으로 들어가니라',7188),
('rut-3-16','rut','룻기',3,16,'룻이 시어머니에게 가니 그가 이르되 내 딸아 어떻게 되었느냐 하니 룻이 그 사람이 자기에게 행한 것을 다 알리고',7189),
('rut-3-17','rut','룻기',3,17,'이르되 그가 내게 이 보리를 여섯 번 되어 주며 이르기를 빈 손으로 네 시어머니에게 가지 말라 하더이다 하니라',7190),
('rut-3-18','rut','룻기',3,18,'이에 시어머니가 이르되 내 딸아 이 사건이 어떻게 될지 알기까지 앉아 있으라 그 사람이 오늘 이 일을 성취하기 전에는 쉬지 아니하리라 하니라',7191),
('rut-4-1','rut','룻기',4,1,'보아스가 성문으로 올라가서 거기 앉아 있더니 마침 보아스가 말하던 기업 무를 자가 지나가는지라 보아스가 그에게 이르되 아무개여 이리로 와서 앉으라 하니 그가 와서 앉으매',7192),
('rut-4-2','rut','룻기',4,2,'보아스가 그 성읍 장로 열 명을 청하여 이르되 당신들은 여기 앉으라 하니 그들이 앉으매',7193),
('rut-4-3','rut','룻기',4,3,'보아스가 그 기업 무를 자에게 이르되 모압 지방에서 돌아온 나오미가 우리 형제 엘리멜렉의 소유지를 팔려 하므로',7194),
('rut-4-4','rut','룻기',4,4,'내가 여기 앉은 이들과 내 백성의 장로들 앞에서 그것을 사라고 네게 말하여 알게 하려 하였노라 만일 네가 무르려면 무르려니와 만일 네가 무르지 아니하려거든 내게 고하여 알게 하라 네 다음은 나요 그 외에는 무를 자가 없느니라 하니 그가 이르되 내가 무르리라 하는지라',7195),
('rut-4-5','rut','룻기',4,5,'보아스가 이르되 네가 나오미의 손에서 그 밭을 사는 날에 곧 죽은 자의 아내 모압 여인 룻에게서 사서 그 죽은 자의 기업을 그의 이름으로 세워야 할지니라 하니',7196),
('rut-4-6','rut','룻기',4,6,'그 기업 무를 자가 이르되 나는 내 기업에 손해가 있을까 하여 나를 위하여 무르지 못하노니 내가 무를 것을 네가 무르라 나는 무르지 못하겠노라 하는지라',7197),
('rut-4-7','rut','룻기',4,7,'옛적 이스라엘 중에는 모든 것을 무르거나 교환하는 일을 확정하기 위하여 사람이 그의 신을 벗어 그의 이웃에게 주더니 이것이 이스라엘 중에 증명하는 전례가 된지라',7198),
('rut-4-8','rut','룻기',4,8,'이에 그 기업 무를 자가 보아스에게 이르되 네가 너를 위하여 사라 하고 그의 신을 벗는지라',7199),
('rut-4-9','rut','룻기',4,9,'보아스가 장로들과 모든 백성에게 이르되 내가 엘리멜렉과 기룐과 말론에게 있던 모든 것을 나오미의 손에서 산 일에 너희가 오늘 증인이 되었고',7200),
('rut-4-10','rut','룻기',4,10,'또 말론의 아내 모압 여인 룻을 사서 나의 아내로 맞이하고 그 죽은 자의 기업을 그의 이름으로 세워 그의 이름이 그의 형제 중과 그 곳 성문에서 끊어지지 아니하게 함에 너희가 오늘 증인이 되었느니라 하니',7201),
('rut-4-11','rut','룻기',4,11,'성문에 있는 모든 백성과 장로들이 이르되 우리가 증인이 되나니 여호와께서 네 집에 들어가는 여인으로 이스라엘의 집을 세운 라헬과 레아 두 사람과 같게 하시고 네가 에브랏에서 유력하고 베들레헴에서 유명하게 하시기를 원하며',7202),
('rut-4-12','rut','룻기',4,12,'여호와께서 이 젊은 여자로 말미암아 네게 상속자를 주사 네 집이 다말이 유다에게 낳아준 베레스의 집과 같게 하시기를 원하노라 하니라',7203),
('rut-4-13','rut','룻기',4,13,'이에 보아스가 룻을 맞이하여 아내로 삼고 그에게 들어갔더니 여호와께서 그에게 임신하게 하시므로 그가 아들을 낳은지라',7204),
('rut-4-14','rut','룻기',4,14,'여인들이 나오미에게 이르되 찬송할지로다 여호와께서 오늘 네게 기업 무를 자가 없게 하지 아니하셨도다 이 아이의 이름이 이스라엘 중에 유명하게 되기를 원하노라',7205),
('rut-4-15','rut','룻기',4,15,'이는 네 생명의 회복자이며 네 노년의 봉양자라 곧 너를 사랑하며 일곱 아들보다 귀한 네 며느리가 낳은 자로다 하니라',7206),
('rut-4-16','rut','룻기',4,16,'나오미가 아기를 받아 품에 품고 그의 양육자가 되니',7207),
('rut-4-17','rut','룻기',4,17,'그의 이웃 여인들이 그에게 이름을 지어 주되 나오미에게 아들이 태어났다 하여 그의 이름을 오벳이라 하였는데 그는 다윗의 아버지인 이새의 아버지였더라',7208),
('rut-4-18','rut','룻기',4,18,'베레스의 계보는 이러하니라 베레스는 헤스론을 낳고',7209),
('rut-4-19','rut','룻기',4,19,'헤스론은 람을 낳았고 람은 암미나답을 낳았고',7210),
('rut-4-20','rut','룻기',4,20,'암미나답은 나손을 낳았고 나손은 살몬을 낳았고',7211),
('rut-4-21','rut','룻기',4,21,'살몬은 보아스를 낳았고 보아스는 오벳을 낳았고',7212),
('rut-4-22','rut','룻기',4,22,'오벳은 이새를 낳고 이새는 다윗을 낳았더라',7213),
('1sa-1-1','1sa','사무엘상',1,1,'에브라임 산지 라마다임소빔에 에브라임 사람 엘가나라 하는 사람이 있었으니 그는 여로함의 아들이요 엘리후의 손자요 도후의 증손이요 숩의 현손이더라',7214),
('1sa-1-2','1sa','사무엘상',1,2,'그에게 두 아내가 있었으니 한 사람의 이름은 한나요 한 사람의 이름은 브닌나라 브닌나에게는 자식이 있고 한나에게는 자식이 없었더라',7215),
('1sa-1-3','1sa','사무엘상',1,3,'이 사람이 매년 자기 성읍에서 나와서 실로에 올라가서 만군의 여호와께 예배하며 제사를 드렸는데 엘리의 두 아들 홉니와 비느하스가 여호와의 제사장으로 거기에 있었더라',7216),
('1sa-1-4','1sa','사무엘상',1,4,'엘가나가 제사를 드리는 날에는 제물의 분깃을 그의 아내 브닌나와 그의 모든 자녀에게 주고',7217),
('1sa-1-5','1sa','사무엘상',1,5,'한나에게는 갑절을 주니 이는 그를 사랑함이라 그러나 여호와께서 그에게 임신하지 못하게 하시니',7218),
('1sa-1-6','1sa','사무엘상',1,6,'여호와께서 그에게 임신하지 못하게 하시므로 그의 적수인 브닌나가 그를 심히 격분하게 하여 괴롭게 하더라',7219),
('1sa-1-7','1sa','사무엘상',1,7,'매년 한나가 여호와의 집에 올라갈 때마다 남편이 그같이 하매 브닌나가 그를 격분시키므로 그가 울고 먹지 아니하니',7220),
('1sa-1-8','1sa','사무엘상',1,8,'그의 남편 엘가나가 그에게 이르되 한나여 어찌하여 울며 어찌하여 먹지 아니하며 어찌하여 그대의 마음이 슬프냐 내가 그대에게 열 아들보다 낫지 아니하냐 하니라',7221),
('1sa-1-9','1sa','사무엘상',1,9,'그들이 실로에서 먹고 마신 후에 한나가 일어나니 그 때에 제사장 엘리는 여호와의 전 문설주 곁 의자에 앉아 있었더라',7222),
('1sa-1-10','1sa','사무엘상',1,10,'한나가 마음이 괴로워서 여호와께 기도하고 통곡하며',7223),
('1sa-1-11','1sa','사무엘상',1,11,'서원하여 이르되 만군의 여호와여 만일 주의 여종의 고통을 돌보시고 나를 기억하사 주의 여종을 잊지 아니하시고 주의 여종에게 아들을 주시면 내가 그의 평생에 그를 여호와께 드리고 삭도를 그의 머리에 대지 아니하겠나이다',7224),
('1sa-1-12','1sa','사무엘상',1,12,'그가 여호와 앞에 오래 기도하는 동안에 엘리가 그의 입을 주목한즉',7225),
('1sa-1-13','1sa','사무엘상',1,13,'한나가 속으로 말하매 입술만 움직이고 음성은 들리지 아니하므로 엘리는 그가 취한 줄로 생각한지라',7226),
('1sa-1-14','1sa','사무엘상',1,14,'엘리가 그에게 이르되 네가 언제까지 취하여 있겠느냐 포도주를 끊으라 하니',7227),
('1sa-1-15','1sa','사무엘상',1,15,'한나가 대답하여 이르되 내 주여 그렇지 아니하니이다 나는 마음이 슬픈 여자라 포도주나 독주를 마신 것이 아니요 여호와 앞에 내 심정을 통한 것뿐이오니',7228),
('1sa-1-16','1sa','사무엘상',1,16,'당신의 여종을 악한 여자로 여기지 마옵소서 내가 지금까지 말한 것은 나의 원통함과 격분됨이 많기 때문이니이다 하는지라',7229),
('1sa-1-17','1sa','사무엘상',1,17,'엘리가 대답하여 이르되 평안히 가라 이스라엘의 하나님이 네가 기도하여 구한 것을 허락하시기를 원하노라 하니',7230),
('1sa-1-18','1sa','사무엘상',1,18,'이르되 당신의 여종이 당신께 은혜 입기를 원하나이다 하고 가서 먹고 얼굴에 다시는 근심 빛이 없더라',7231),
('1sa-1-19','1sa','사무엘상',1,19,'그들이 아침에 일찍이 일어나 여호와 앞에 경배하고 돌아가 라마의 자기 집에 이르니라 엘가나가 그의 아내 한나와 동침하매 여호와께서 그를 생각하신지라',7232),
('1sa-1-20','1sa','사무엘상',1,20,'한나가 임신하고 때가 이르매 아들을 낳아 사무엘이라 이름하였으니 이는 내가 여호와께 그를 구하였다 함이더라',7233),
('1sa-1-21','1sa','사무엘상',1,21,'그 사람 엘가나와 그의 온 집이 여호와께 매년제와 서원제를 드리러 올라갈 때에',7234),
('1sa-1-22','1sa','사무엘상',1,22,'오직 한나는 올라가지 아니하고 그의 남편에게 이르되 아이를 젖 떼거든 내가 그를 데리고 가서 여호와 앞에 뵙게 하고 거기에 영원히 있게 하리이다 하니',7235),
('1sa-1-23','1sa','사무엘상',1,23,'그의 남편 엘가나가 그에게 이르되 그대의 소견에 좋은 대로 하여 그를 젖 떼기까지 기다리라 오직 여호와께서 그의 말씀대로 이루시기를 원하노라 하니라 이에 그 여자가 그의 아들을 양육하며 그가 젖 떼기까지 기다리다가',7236),
('1sa-1-24','1sa','사무엘상',1,24,'젖을 뗀 후에 그를 데리고 올라갈새 수소 세 마리와 밀가루 한 에바와 포도주 한 가죽부대를 가지고 실로 여호와의 집에 나아갔는데 아이가 어리더라',7237),
('1sa-1-25','1sa','사무엘상',1,25,'그들이 수소를 잡고 아이를 데리고 엘리에게 가서',7238),
('1sa-1-26','1sa','사무엘상',1,26,'한나가 이르되 내 주여 당신의 사심으로 맹세하나이다 나는 여기서 내 주 당신 곁에 서서 여호와께 기도하던 여자라',7239),
('1sa-1-27','1sa','사무엘상',1,27,'이 아이를 위하여 내가 기도하였더니 내가 구하여 기도한 바를 여호와께서 내게 허락하신지라',7240),
('1sa-1-28','1sa','사무엘상',1,28,'그러므로 나도 그를 여호와께 드리되 그의 평생을 여호와께 드리나이다 하고 그가 거기서 여호와께 경배하니라',7241),
('1sa-2-1','1sa','사무엘상',2,1,'한나가 기도하여 이르되 내 마음이 여호와로 말미암아 즐거워하며 내 뿔이 여호와로 말미암아 높아졌으며 내 입이 내 원수들을 향하여 크게 열렸으니 이는 내가 주의 구원으로 말미암아 기뻐함이니이다',7242),
('1sa-2-2','1sa','사무엘상',2,2,'여호와와 같이 거룩하신 이가 없으시니 이는 주 밖에 다른 이가 없고 우리 하나님 같은 반석도 없으심이니이다',7243),
('1sa-2-3','1sa','사무엘상',2,3,'심히 교만한 말을 다시 하지 말 것이며 오만한 말을 너희의 입에서 내지 말지어다 여호와는 지식의 하나님이시라 행동을 달아 보시느니라',7244),
('1sa-2-4','1sa','사무엘상',2,4,'용사의 활은 꺾이고 넘어진 자는 힘으로 띠를 띠도다',7245),
('1sa-2-5','1sa','사무엘상',2,5,'풍족하던 자들은 양식을 위하여 품을 팔고 주리던 자들은 다시 주리지 아니하도다 전에 임신하지 못하던 자는 일곱을 낳았고 많은 자녀를 둔 자는 쇠약하도다',7246),
('1sa-2-6','1sa','사무엘상',2,6,'여호와는 죽이기도 하시고 살리기도 하시며 스올에 내리게도 하시고 거기에서 올리기도 하시는도다',7247),
('1sa-2-7','1sa','사무엘상',2,7,'여호와는 가난하게도 하시고 부하게도 하시며 낮추기도 하시고 높이기도 하시는도다',7248),
('1sa-2-8','1sa','사무엘상',2,8,'가난한 자를 진토에서 일으키시며 빈궁한 자를 거름더미에서 올리사 귀족들과 함께 앉게 하시며 영광의 자리를 차지하게 하시는도다 땅의 기둥들은 여호와의 것이라 여호와께서 세계를 그것들 위에 세우셨도다',7249),
('1sa-2-9','1sa','사무엘상',2,9,'그가 그의 거룩한 자들의 발을 지키실 것이요 악인들을 흑암 중에서 잠잠하게 하시리니 힘으로는 이길 사람이 없음이로다',7250),
('1sa-2-10','1sa','사무엘상',2,10,'여호와를 대적하는 자는 산산이 깨어질 것이라 하늘에서 우레로 그들을 치시리로다 여호와께서 땅 끝까지 심판을 내리시고 자기 왕에게 힘을 주시며 자기의 기름 부음을 받은 자의 뿔을 높이시리로다 하니라',7251),
('1sa-2-11','1sa','사무엘상',2,11,'엘가나는 라마의 자기 집으로 돌아가고 그 아이는 제사장 엘리 앞에서 여호와를 섬기니라',7252),
('1sa-2-12','1sa','사무엘상',2,12,'엘리의 아들들은 행실이 나빠 여호와를 알지 못하더라',7253),
('1sa-2-13','1sa','사무엘상',2,13,'그 제사장들이 백성에게 행하는 관습은 이러하니 곧 어떤 사람이 제사를 드리고 그 고기를 삶을 때에 제사장의 사환이 손에 세 살 갈고리를 가지고 와서',7254),
('1sa-2-14','1sa','사무엘상',2,14,'그것으로 냄비에나 솥에나 큰 솥에나 가마에 찔러 넣어 갈고리에 걸려 나오는 것은 제사장이 자기 것으로 가지되 실로에서 그 곳에 온 모든 이스라엘 사람에게 이같이 할 뿐 아니라',7255),
('1sa-2-15','1sa','사무엘상',2,15,'기름을 태우기 전에도 제사장의 사환이 와서 제사 드리는 사람에게 이르기를 제사장에게 구워 드릴 고기를 내라 그가 네게 삶은 고기를 원하지 아니하고 날 것을 원하신다 하다가',7256),
('1sa-2-16','1sa','사무엘상',2,16,'그 사람이 이르기를 반드시 먼저 기름을 태운 후에 네 마음에 원하는 대로 가지라 하면 그가 말하기를 아니라 지금 내게 내라 그렇지 아니하면 내가 억지로 빼앗으리라 하였으니',7257),
('1sa-2-17','1sa','사무엘상',2,17,'이 소년들의 죄가 여호와 앞에 심히 큼은 그들이 여호와의 제사를 멸시함이었더라',7258),
('1sa-2-18','1sa','사무엘상',2,18,'사무엘은 어렸을 때에 세마포 에봇을 입고 여호와 앞에서 섬겼더라',7259),
('1sa-2-19','1sa','사무엘상',2,19,'그의 어머니가 매년 드리는 제사를 드리러 그의 남편과 함께 올라갈 때마다 작은 겉옷을 지어다가 그에게 주었더니',7260),
('1sa-2-20','1sa','사무엘상',2,20,'엘리가 엘가나와 그의 아내에게 축복하여 이르되 여호와께서 이 여인으로 말미암아 네게 다른 후사를 주사 이가 여호와께 간구하여 얻어 바친 아들을 대신하게 하시기를 원하노라 하였더니 그들이 자기 집으로 돌아가매',7261),
('1sa-2-21','1sa','사무엘상',2,21,'여호와께서 한나를 돌보시사 그로 하여금 임신하여 세 아들과 두 딸을 낳게 하셨고 아이 사무엘은 여호와 앞에서 자라니라',7262),
('1sa-2-22','1sa','사무엘상',2,22,'엘리가 매우 늙었더니 그의 아들들이 온 이스라엘에게 행한 모든 일과 회막 문에서 수종 드는 여인들과 동침하였음을 듣고',7263),
('1sa-2-23','1sa','사무엘상',2,23,'그들에게 이르되 너희가 어찌하여 이런 일을 하느냐 내가 너희의 악행을 이 모든 백성에게서 듣노라',7264),
('1sa-2-24','1sa','사무엘상',2,24,'내 아들들아 그리하지 말라 내게 들리는 소문이 좋지 아니하니라 너희가 여호와의 백성으로 범죄하게 하는도다',7265),
('1sa-2-25','1sa','사무엘상',2,25,'사람이 사람에게 범죄하면 하나님이 심판하시려니와 만일 사람이 여호와께 범죄하면 누가 그를 위하여 간구하겠느냐 하되 그들이 자기 아버지의 말을 듣지 아니하였으니 이는 여호와께서 그들을 죽이기로 뜻하셨음이더라',7266),
('1sa-2-26','1sa','사무엘상',2,26,'아이 사무엘이 점점 자라매 여호와와 사람들에게 은총을 더욱 받더라',7267),
('1sa-2-27','1sa','사무엘상',2,27,'하나님의 사람이 엘리에게 와서 그에게 이르되 여호와의 말씀에 너희 조상의 집이 애굽에서 바로의 집에 속하였을 때에 내가 그들에게 나타나지 아니하였느냐',7268),
('1sa-2-28','1sa','사무엘상',2,28,'이스라엘 모든 지파 중에서 내가 그를 택하여 내 제사장으로 삼아 그가 내 제단에 올라 분향하며 내 앞에서 에봇을 입게 하지 아니하였느냐 이스라엘 자손이 드리는 모든 화제를 내가 네 조상의 집에 주지 아니하였느냐',7269),
('1sa-2-29','1sa','사무엘상',2,29,'너희는 어찌하여 내가 내 처소에서 명령한 내 제물과 예물을 밟으며 네 아들들을 나보다 더 중히 여겨 내 백성 이스라엘이 드리는 가장 좋은 것으로 너희들을 살지게 하느냐',7270),
('1sa-2-30','1sa','사무엘상',2,30,'그러므로 이스라엘의 하나님 나 여호와가 말하노라 내가 전에 네 집과 네 조상의 집이 내 앞에 영원히 행하리라 하였으나 이제 나 여호와가 말하노니 결단코 그렇게 하지 아니하리라 나를 존중히 여기는 자를 내가 존중히 여기고 나를 멸시하는 자를 내가 경멸하리라',7271),
('1sa-2-31','1sa','사무엘상',2,31,'보라 내가 네 팔과 네 조상의 집 팔을 끊어 네 집에 노인이 하나도 없게 하는 날이 이를지라',7272),
('1sa-2-32','1sa','사무엘상',2,32,'이스라엘에게 모든 복을 내리는 중에 너는 내 처소의 환난을 볼 것이요 네 집에 영원토록 노인이 없을 것이며',7273),
('1sa-2-33','1sa','사무엘상',2,33,'내 제단에서 내가 끊어 버리지 아니할 네 사람이 네 눈을 쇠잔하게 하고 네 마음을 슬프게 할 것이요 네 집에서 출산되는 모든 자가 젊어서 죽으리라',7274),
('1sa-2-34','1sa','사무엘상',2,34,'네 두 아들 홉니와 비느하스가 한 날에 죽으리니 그 둘이 당할 그 일이 네게 표징이 되리라',7275),
('1sa-2-35','1sa','사무엘상',2,35,'내가 나를 위하여 충실한 제사장을 일으키리니 그 사람은 내 마음, 내 뜻대로 행할 것이라 내가 그를 위하여 견고한 집을 세우리니 그가 나의 기름 부음을 받은 자 앞에서 영구히 행하리라',7276),
('1sa-2-36','1sa','사무엘상',2,36,'그리고 네 집에 남은 사람이 각기 와서 은 한 조각과 떡 한 덩이를 위하여 그에게 엎드려 이르되 청하노니 내게 제사장의 직분 하나를 맡겨 내게 떡 조각을 먹게 하소서 하리라 하셨다 하니라',7277),
('1sa-3-1','1sa','사무엘상',3,1,'아이 사무엘이 엘리 앞에서 여호와를 섬길 때에는 여호와의 말씀이 희귀하여 이상이 흔히 보이지 않았더라',7278),
('1sa-3-2','1sa','사무엘상',3,2,'엘리의 눈이 점점 어두워 가서 잘 보지 못하는 그 때에 그가 자기 처소에 누웠고',7279),
('1sa-3-3','1sa','사무엘상',3,3,'하나님의 등불은 아직 꺼지지 아니하였으며 사무엘은 하나님의 궤 있는 여호와의 전 안에 누웠더니',7280),
('1sa-3-4','1sa','사무엘상',3,4,'여호와께서 사무엘을 부르시는지라 그가 대답하되 내가 여기 있나이다 하고',7281),
('1sa-3-5','1sa','사무엘상',3,5,'엘리에게로 달려가서 이르되 당신이 나를 부르셨기로 내가 여기 있나이다 하니 그가 이르되 나는 부르지 아니하였으니 다시 누우라 하는지라 그가 가서 누웠더니',7282),
('1sa-3-6','1sa','사무엘상',3,6,'여호와께서 다시 사무엘을 부르시는지라 사무엘이 일어나 엘리에게로 가서 이르되 당신이 나를 부르셨기로 내가 여기 있나이다 하니 그가 대답하되 내 아들아 내가 부르지 아니하였으니 다시 누우라 하니라',7283),
('1sa-3-7','1sa','사무엘상',3,7,'사무엘이 아직 여호와를 알지 못하고 여호와의 말씀도 아직 그에게 나타나지 아니한 때라',7284),
('1sa-3-8','1sa','사무엘상',3,8,'여호와께서 세 번째 사무엘을 부르시는지라 그가 일어나 엘리에게로 가서 이르되 당신이 나를 부르셨기로 내가 여기 있나이다 하니 엘리가 여호와께서 이 아이를 부르신 줄을 깨닫고',7285),
('1sa-3-9','1sa','사무엘상',3,9,'엘리가 사무엘에게 이르되 가서 누웠다가 그가 너를 부르시거든 네가 말하기를 여호와여 말씀하옵소서 주의 종이 듣겠나이다 하라 하니 이에 사무엘이 가서 자기 처소에 누우니라',7286),
('1sa-3-10','1sa','사무엘상',3,10,'여호와께서 임하여 서서 전과 같이 사무엘아 사무엘아 부르시는지라 사무엘이 이르되 말씀하옵소서 주의 종이 듣겠나이다 하니',7287),
('1sa-3-11','1sa','사무엘상',3,11,'여호와께서 사무엘에게 이르시되 보라 내가 이스라엘 중에 한 일을 행하리니 그것을 듣는 자마다 두 귀가 울리리라',7288),
('1sa-3-12','1sa','사무엘상',3,12,'내가 엘리의 집에 대하여 말한 것을 처음부터 끝까지 그 날에 그에게 다 이루리라',7289),
('1sa-3-13','1sa','사무엘상',3,13,'내가 그의 집을 영원토록 심판하겠다고 그에게 말한 것은 그가 아는 죄악 때문이니 이는 그가 자기의 아들들이 저주를 자청하되 금하지 아니하였음이니라',7290),
('1sa-3-14','1sa','사무엘상',3,14,'그러므로 내가 엘리의 집에 대하여 맹세하기를 엘리 집의 죄악은 제물로나 예물로나 영원히 속죄함을 받지 못하리라 하였노라 하셨더라',7291),
('1sa-3-15','1sa','사무엘상',3,15,'사무엘이 아침까지 누웠다가 여호와의 집의 문을 열었으나 그 이상을 엘리에게 알게 하기를 두려워하더니',7292),
('1sa-3-16','1sa','사무엘상',3,16,'엘리가 사무엘을 불러 이르되 내 아들 사무엘아 하니 그가 대답하되 내가 여기 있나이다 하니 그가',7293),
('1sa-3-17','1sa','사무엘상',3,17,'이르되 네게 무엇을 말씀하셨느냐 청하노니 내게 숨기지 말라 네게 말씀하신 모든 것을 하나라도 숨기면 하나님이 네게 벌을 내리시고 또 내리시기를 원하노라 하는지라',7294),
('1sa-3-18','1sa','사무엘상',3,18,'사무엘이 그것을 그에게 자세히 말하고 조금도 숨기지 아니하니 그가 이르되 이는 여호와이시니 선하신 대로 하실 것이니라 하니라',7295),
('1sa-3-19','1sa','사무엘상',3,19,'사무엘이 자라매 여호와께서 그와 함께 계셔서 그의 말이 하나도 땅에 떨어지지 않게 하시니',7296),
('1sa-3-20','1sa','사무엘상',3,20,'단에서부터 브엘세바까지의 온 이스라엘이 사무엘은 여호와의 선지자로 세우심을 입은 줄을 알았더라',7297),
('1sa-3-21','1sa','사무엘상',3,21,'여호와께서 실로에서 다시 나타나시되 여호와께서 실로에서 여호와의 말씀으로 사무엘에게 자기를 나타내시니라',7298),
('1sa-4-1','1sa','사무엘상',4,1,'사무엘의 말이 온 이스라엘에 전파되니라. 이스라엘은 나가서 블레셋 사람들과 싸우려고 에벤에셀 곁에 진 치고 블레셋 사람들은 아벡에 진 쳤더니',7299),
('1sa-4-2','1sa','사무엘상',4,2,'블레셋 사람들이 이스라엘에 대하여 전열을 벌이니라 그 둘이 싸우다가 이스라엘이 블레셋 사람들 앞에서 패하여 그들에게 전쟁에서 죽임을 당한 군사가 사천 명 가량이라',7300),
('1sa-4-3','1sa','사무엘상',4,3,'백성이 진영으로 돌아오매 이스라엘 장로들이 이르되 여호와께서 어찌하여 우리에게 오늘 블레셋 사람들 앞에 패하게 하셨는고 여호와의 언약궤를 실로에서 우리에게로 가져다가 우리 중에 있게 하여 그것으로 우리를 우리 원수들의 손에서 구원하게 하자 하니',7301),
('1sa-4-4','1sa','사무엘상',4,4,'이에 백성이 실로에 사람을 보내어 그룹 사이에 계신 만군의 여호와의 언약궤를 거기서 가져왔고 엘리의 두 아들 홉니와 비느하스는 하나님의 언약궤와 함께 거기에 있었더라',7302),
('1sa-4-5','1sa','사무엘상',4,5,'여호와의 언약궤가 진영에 들어올 때에 온 이스라엘이 큰 소리로 외치매 땅이 울린지라',7303),
('1sa-4-6','1sa','사무엘상',4,6,'블레셋 사람이 그 외치는 소리를 듣고 이르되 히브리 진영에서 큰 소리로 외침은 어찌 됨이냐 하다가 여호와의 궤가 진영에 들어온 줄을 깨달은지라',7304),
('1sa-4-7','1sa','사무엘상',4,7,'블레셋 사람이 두려워하여 이르되 신이 진영에 이르렀도다 하고 또 이르되 우리에게 화로다 전날에는 이런 일이 없었도다',7305),
('1sa-4-8','1sa','사무엘상',4,8,'우리에게 화로다 누가 우리를 이 능한 신들의 손에서 건지리요 그들은 광야에서 여러 가지 재앙으로 애굽인을 친 신들이니라',7306),
('1sa-4-9','1sa','사무엘상',4,9,'너희 블레셋 사람들아 강하게 되며 대장부가 되라 너희가 히브리 사람의 종이 되기를 그들이 너희의 종이 되었던 것 같이 되지 말고 대장부 같이 되어 싸우라 하고',7307),
('1sa-4-10','1sa','사무엘상',4,10,'블레셋 사람들이 쳤더니 이스라엘이 패하여 각기 장막으로 도망하였고 살륙이 심히 커서 이스라엘 보병의 엎드러진 자가 삼만 명이었으며',7308),
('1sa-4-11','1sa','사무엘상',4,11,'하나님의 궤는 빼앗겼고 엘리의 두 아들 홉니와 비느하스는 죽임을 당하였더라',7309),
('1sa-4-12','1sa','사무엘상',4,12,'당일에 어떤 베냐민 사람이 진영에서 달려나와 자기의 옷을 찢고 자기의 머리에 티끌을 덮어쓰고 실로에 이르니라',7310),
('1sa-4-13','1sa','사무엘상',4,13,'그가 이를 때는 엘리가 길 옆 자기의 의자에 앉아 기다리며 그의 마음이 하나님의 궤로 말미암아 떨릴 즈음이라 그 사람이 성읍에 들어오며 알리매 온 성읍이 부르짖는지라',7311),
('1sa-4-14','1sa','사무엘상',4,14,'엘리가 그 부르짖는 소리를 듣고 이르되 이 떠드는 소리는 어찌 됨이냐 그 사람이 빨리 가서 엘리에게 말하니',7312),
('1sa-4-15','1sa','사무엘상',4,15,'그 때에 엘리의 나이가 구십팔 세라 그의 눈이 어두워서 보지 못하더라',7313),
('1sa-4-16','1sa','사무엘상',4,16,'그 사람이 엘리에게 말하되 나는 진중에서 나온 자라 내가 오늘 진중에서 도망하여 왔나이다 엘리가 이르되 내 아들아 일이 어떻게 되었느냐',7314),
('1sa-4-17','1sa','사무엘상',4,17,'소식을 전하는 자가 대답하여 이르되 이스라엘이 블레셋 사람들 앞에서 도망하였고 백성 중에는 큰 살륙이 있었고 당신의 두 아들 홉니와 비느하스도 죽임을 당하였고 하나님의 궤는 빼앗겼나이다',7315),
('1sa-4-18','1sa','사무엘상',4,18,'하나님의 궤를 말할 때에 엘리가 자기 의자에서 뒤로 넘어져 문 곁에서 목이 부러져 죽었으니 나이가 많고 비대한 까닭이라 그가 이스라엘의 사사가 된 지 사십 년이었더라',7316),
('1sa-4-19','1sa','사무엘상',4,19,'그의 며느리인 비느하스의 아내가 임신하여 해산 때가 가까웠더니 하나님의 궤를 빼앗긴 것과 그의 시아버지와 남편이 죽은 소식을 듣고 갑자기 아파서 몸을 구푸려 해산하고',7317),
('1sa-4-20','1sa','사무엘상',4,20,'죽어갈 때에 곁에 서 있던 여인들이 그에게 이르되 두려워하지 말라 네가 아들을 낳았다 하되 그가 대답하지도 아니하며 관념하지도 아니하고',7318),
('1sa-4-21','1sa','사무엘상',4,21,'이르기를 영광이 이스라엘에서 떠났다 하고 아이 이름을 이가봇이라 하였으니 하나님의 궤가 빼앗겼고 그의 시아버지와 남편이 죽었기 때문이며',7319),
('1sa-4-22','1sa','사무엘상',4,22,'또 이르기를 하나님의 궤를 빼앗겼으므로 영광이 이스라엘에서 떠났다 하였더라',7320),
('1sa-5-1','1sa','사무엘상',5,1,'블레셋 사람들이 하나님의 궤를 빼앗아 가지고 에벤에셀에서부터 아스돗에 이르니라',7321),
('1sa-5-2','1sa','사무엘상',5,2,'블레셋 사람들이 하나님의 궤를 가지고 다곤의 신전에 들어가서 다곤 곁에 두었더니',7322),
('1sa-5-3','1sa','사무엘상',5,3,'아스돗 사람들이 이튿날 일찍이 일어나 본즉 다곤이 여호와의 궤 앞에서 엎드러져 그 얼굴이 땅에 닿았는지라 그들이 다곤을 일으켜 다시 그 자리에 세웠더니',7323),
('1sa-5-4','1sa','사무엘상',5,4,'그 이튿날 아침에 그들이 일찍이 일어나 본즉 다곤이 여호와의 궤 앞에서 또다시 엎드러져 얼굴이 땅에 닿았고 그 머리와 두 손목은 끊어져 문지방에 있고 다곤의 몸뚱이만 남았더라',7324),
('1sa-5-5','1sa','사무엘상',5,5,'그러므로 다곤의 제사장들이나 다곤의 신전에 들어가는 자는 오늘까지 아스돗에 있는 다곤의 문지방을 밟지 아니하더라',7325),
('1sa-5-6','1sa','사무엘상',5,6,'여호와의 손이 아스돗 사람에게 엄중히 더하사 독한 종기의 재앙으로 아스돗과 그 지역을 쳐서 망하게 하니',7326),
('1sa-5-7','1sa','사무엘상',5,7,'아스돗 사람들이 이를 보고 이르되 이스라엘 신의 궤를 우리와 함께 있지 못하게 할지라 그의 손이 우리와 우리 신 다곤을 친다 하고',7327),
('1sa-5-8','1sa','사무엘상',5,8,'이에 사람을 보내어 블레셋 사람들의 모든 방백을 모으고 이르되 우리가 이스라엘 신의 궤를 어찌하랴 하니 그들이 대답하되 이스라엘 신의 궤를 가드로 옮겨 가라 하므로 이스라엘 신의 궤를 옮겨 갔더니',7328),
('1sa-5-9','1sa','사무엘상',5,9,'그것을 옮겨 간 후에 여호와의 손이 심히 큰 환난을 그 성읍에 더하사 성읍 사람들의 작은 자와 큰 자를 다 쳐서 독한 종기가 나게 하신지라',7329),
('1sa-5-10','1sa','사무엘상',5,10,'이에 그들이 하나님의 궤를 에그론으로 보내니라 하나님의 궤가 에그론에 이른즉 에그론 사람이 부르짖어 이르되 그들이 이스라엘 신의 궤를 우리에게로 가져다가 우리와 우리 백성을 죽이려 한다 하고',7330),
('1sa-5-11','1sa','사무엘상',5,11,'이에 사람을 보내어 블레셋 모든 방백을 모으고 이르되 이스라엘 신의 궤를 보내어 그 있던 곳으로 돌아가게 하고 우리와 우리 백성이 죽임을 면하게 하자 하니 이는 온 성읍이 사망의 환난을 당함이라 거기서 하나님의 손이 엄중하시므로',7331),
('1sa-5-12','1sa','사무엘상',5,12,'죽지 아니한 사람들은 독한 종기로 치심을 당해 성읍의 부르짖음이 하늘에 사무쳤더라',7332),
('1sa-6-1','1sa','사무엘상',6,1,'여호와의 궤가 블레셋 사람들의 지방에 있은 지 일곱 달이라',7333),
('1sa-6-2','1sa','사무엘상',6,2,'블레셋 사람들이 제사장들과 복술자들을 불러서 이르되 우리가 여호와의 궤를 어떻게 할까 그것을 어떻게 그 있던 곳으로 보낼 것인지 우리에게 가르치라',7334),
('1sa-6-3','1sa','사무엘상',6,3,'그들이 이르되 이스라엘 신의 궤를 보내려거든 거저 보내지 말고 그에게 속건제를 드려야 할지니라 그리하면 병도 낫고 그의 손을 너희에게서 옮기지 아니하는 이유도 알리라 하니',7335),
('1sa-6-4','1sa','사무엘상',6,4,'그들이 이르되 무엇으로 그에게 드릴 속건제를 삼을까 하니 이르되 블레셋 사람의 방백의 수효대로 금 독종 다섯과 금 쥐 다섯 마리라야 하리니 너희와 너희 통치자에게 내린 재앙이 같음이니라',7336),
('1sa-6-5','1sa','사무엘상',6,5,'그러므로 너희는 너희의 독한 종기의 형상과 땅을 해롭게 하는 쥐의 형상을 만들어 이스라엘 신께 영광을 돌리라 그가 혹 그의 손을 너희와 너희의 신들과 너희 땅에서 가볍게 하실까 하노라',7337),
('1sa-6-6','1sa','사무엘상',6,6,'애굽인과 바로가 그들의 마음을 완악하게 한 것 같이 어찌하여 너희가 너희의 마음을 완악하게 하겠느냐 그가 그들 중에서 재앙을 내린 후에 그들이 백성을 가게 하므로 백성이 떠나지 아니하였느냐',7338),
('1sa-6-7','1sa','사무엘상',6,7,'그러므로 새 수레를 하나 만들고 멍에를 메어 보지 아니한 젖 나는 소 두 마리를 끌어다가 소에 수레를 메우고 그 송아지들은 떼어 집으로 돌려보내고',7339),
('1sa-6-8','1sa','사무엘상',6,8,'여호와의 궤를 가져다가 수레에 싣고 속건제로 드릴 금으로 만든 물건들은 상자에 담아 궤 곁에 두고 그것을 보내어 가게 하고',7340),
('1sa-6-9','1sa','사무엘상',6,9,'보고 있다가 만일 궤가 그 본 지역 길로 올라가서 벧세메스로 가면 이 큰 재앙은 그가 우리에게 내린 것이요 그렇지 아니하면 우리를 친 것이 그의 손이 아니요 우연히 당한 것인 줄 알리라 하니라',7341),
('1sa-6-10','1sa','사무엘상',6,10,'그 사람들이 그같이 하여 젖 나는 소 둘을 끌어다가 수레를 메우고 송아지들은 집에 가두고',7342),
('1sa-6-11','1sa','사무엘상',6,11,'여호와의 궤와 및 금 쥐와 그들의 독종의 형상을 담은 상자를 수레 위에 실으니',7343),
('1sa-6-12','1sa','사무엘상',6,12,'암소가 벧세메스 길로 바로 행하여 대로로 가며 갈 때에 울고 좌우로 치우치지 아니하였고 블레셋 방백들은 벧세메스 경계선까지 따라 가니라',7344),
('1sa-6-13','1sa','사무엘상',6,13,'벧세메스 사람들이 골짜기에서 밀을 베다가 눈을 들어 궤를 보고 그 본 것을 기뻐하더니',7345),
('1sa-6-14','1sa','사무엘상',6,14,'수레가 벧세메스 사람 여호수아의 밭 큰 돌 있는 곳에 이르러 선지라 무리가 수레의 나무를 패고 그 암소들을 번제물로 여호와께 드리고',7346),
('1sa-6-15','1sa','사무엘상',6,15,'레위인은 여호와의 궤와 그 궤와 함께 있는 금 보물 담긴 상자를 내려다가 큰 돌 위에 두매 그 날에 벧세메스 사람들이 여호와께 번제와 다른 제사를 드리니라',7347),
('1sa-6-16','1sa','사무엘상',6,16,'블레셋 다섯 방백이 이것을 보고 그 날에 에그론으로 돌아갔더라',7348),
('1sa-6-17','1sa','사무엘상',6,17,'블레셋 사람이 여호와께 속건제물로 드린 금 독종은 이러하니 아스돗을 위하여 하나요 가사를 위하여 하나요 아스글론을 위하여 하나요 가드를 위하여 하나요 에그론을 위하여 하나이며',7349),
('1sa-6-18','1sa','사무엘상',6,18,'드린 바 금 쥐들은 견고한 성읍에서부터 시골의 마을에까지 그리고 사람들이 여호와의 궤를 큰 돌에 이르기까지 다섯 방백들에게 속한 블레셋 사람들의 모든 성읍들의 수대로였더라 그 돌은 벧세메스 사람 여호수아의 밭에 오늘까지 있더라',7350),
('1sa-6-19','1sa','사무엘상',6,19,'벧세메스 사람들이 여호와의 궤를 들여다 본 까닭에 그들을 치사 (오만) 칠십 명을 죽이신지라 여호와께서 백성을 쳐서 크게 살륙하셨으므로 백성이 슬피 울었더라',7351),
('1sa-6-20','1sa','사무엘상',6,20,'벧세메스 사람들이 이르되 이 거룩하신 하나님 여호와 앞에 누가 능히 서리요 그를 우리에게서 누구에게로 올라가시게 할까 하고',7352),
('1sa-6-21','1sa','사무엘상',6,21,'전령들을 기럇여아림 주민에게 보내어 이르되 블레셋 사람들이 여호와의 궤를 도로 가져왔으니 너희는 내려와서 그것을 너희에게로 옮겨 가라',7353),
('1sa-7-1','1sa','사무엘상',7,1,'기럇여아림 사람들이 와서 여호와의 궤를 옮겨 산에 사는 아비나답의 집에 들여놓고 그의 아들 엘리아살을 거룩하게 구별하여 여호와의 궤를 지키게 하였더니',7354),
('1sa-7-2','1sa','사무엘상',7,2,'궤가 기럇여아림에 들어간 날부터 이십 년 동안 오래 있은지라 이스라엘 온 족속이 여호와를 사모하니라',7355),
('1sa-7-3','1sa','사무엘상',7,3,'사무엘이 이스라엘 온 족속에게 말하여 이르되 만일 너희가 전심으로 여호와께 돌아오려거든 이방 신들과 아스다롯을 너희 중에서 제거하고 너희 마음을 여호와께로 향하여 그만을 섬기라 그리하면 너희를 블레셋 사람의 손에서 건져내시리라',7356),
('1sa-7-4','1sa','사무엘상',7,4,'이에 이스라엘 자손이 바알들과 아스다롯을 제거하고 여호와만 섬기니라',7357),
('1sa-7-5','1sa','사무엘상',7,5,'사무엘이 이르되 온 이스라엘은 미스바로 모이라 내가 너희를 위하여 여호와께 기도하리라 하매',7358),
('1sa-7-6','1sa','사무엘상',7,6,'그들이 미스바에 모여 물을 길어 여호와 앞에 붓고 그 날 종일 금식하고 거기에서 이르되 우리가 여호와께 범죄하였나이다 하니라 사무엘이 미스바에서 이스라엘 자손을 다스리니라',7359),
('1sa-7-7','1sa','사무엘상',7,7,'이스라엘 자손이 미스바에 모였다 함을 블레셋 사람들이 듣고 그들의 방백들이 이스라엘을 치러 올라온지라 이스라엘 자손들이 듣고 블레셋 사람들을 두려워하여',7360),
('1sa-7-8','1sa','사무엘상',7,8,'이스라엘 자손이 사무엘에게 이르되 당신은 우리를 위하여 우리 하나님 여호와께 쉬지 말고 부르짖어 우리를 블레셋 사람들의 손에서 구원하시게 하소서 하니',7361),
('1sa-7-9','1sa','사무엘상',7,9,'사무엘이 젖 먹는 어린 양 하나를 가져다가 온전한 번제를 여호와께 드리고 이스라엘을 위하여 여호와께 부르짖으매 여호와께서 응답하셨더라',7362),
('1sa-7-10','1sa','사무엘상',7,10,'사무엘이 번제를 드릴 때에 블레셋 사람이 이스라엘과 싸우려고 가까이 오매 그 날에 여호와께서 블레셋 사람에게 큰 우레를 발하여 그들을 어지럽게 하시니 그들이 이스라엘 앞에 패한지라',7363),
('1sa-7-11','1sa','사무엘상',7,11,'이스라엘 사람들이 미스바에서 나가서 블레셋 사람들을 추격하여 벧갈 아래에 이르기까지 쳤더라',7364),
('1sa-7-12','1sa','사무엘상',7,12,'사무엘이 돌을 취하여 미스바와 센 사이에 세워 이르되 여호와께서 여기까지 우리를 도우셨다 하고 그 이름을 에벤에셀이라 하니라',7365),
('1sa-7-13','1sa','사무엘상',7,13,'이에 블레셋 사람들이 굴복하여 다시는 이스라엘 지역 안에 들어오지 못하였으며 여호와의 손이 사무엘이 사는 날 동안에 블레셋 사람을 막으시매',7366),
('1sa-7-14','1sa','사무엘상',7,14,'블레셋 사람들이 이스라엘에게서 빼앗았던 성읍이 에그론부터 가드까지 이스라엘에게 회복되니 이스라엘이 그 사방 지역을 블레셋 사람들의 손에서 도로 찾았고 또 이스라엘과 아모리 사람 사이에 평화가 있었더라',7367),
('1sa-7-15','1sa','사무엘상',7,15,'사무엘이 사는 날 동안에 이스라엘을 다스렸으되',7368),
('1sa-7-16','1sa','사무엘상',7,16,'해마다 벧엘과 길갈과 미스바로 순회하여 그 모든 곳에서 이스라엘을 다스렸고',7369),
('1sa-7-17','1sa','사무엘상',7,17,'라마로 돌아왔으니 이는 거기에 자기 집이 있음이니라 거기서도 이스라엘을 다스렸으며 또 거기에 여호와를 위하여 제단을 쌓았더라',7370),
('1sa-8-1','1sa','사무엘상',8,1,'사무엘이 늙으매 그의 아들들을 이스라엘 사사로 삼으니',7371),
('1sa-8-2','1sa','사무엘상',8,2,'장자의 이름은 요엘이요 차자의 이름은 아비야라 그들이 브엘세바에서 사사가 되니라',7372),
('1sa-8-3','1sa','사무엘상',8,3,'그의 아들들이 자기 아버지의 행위를 따르지 아니하고 이익을 따라 뇌물을 받고 판결을 굽게 하니라',7373),
('1sa-8-4','1sa','사무엘상',8,4,'이스라엘 모든 장로가 모여 라마에 있는 사무엘에게 나아가서',7374),
('1sa-8-5','1sa','사무엘상',8,5,'그에게 이르되 보소서 당신은 늙고 당신의 아들들은 당신의 행위를 따르지 아니하니 모든 나라와 같이 우리에게 왕을 세워 우리를 다스리게 하소서 한지라',7375),
('1sa-8-6','1sa','사무엘상',8,6,'우리에게 왕을 주어 우리를 다스리게 하라 했을 때에 사무엘이 그것을 기뻐하지 아니하여 여호와께 기도하매',7376),
('1sa-8-7','1sa','사무엘상',8,7,'여호와께서 사무엘에게 이르시되 백성이 네게 한 말을 다 들으라 이는 그들이 너를 버림이 아니요 나를 버려 자기들의 왕이 되지 못하게 함이니라',7377),
('1sa-8-8','1sa','사무엘상',8,8,'내가 그들을 애굽에서 인도하여 낸 날부터 오늘까지 그들이 모든 행사로 나를 버리고 다른 신들을 섬김 같이 네게도 그리하는도다',7378),
('1sa-8-9','1sa','사무엘상',8,9,'그러므로 그들의 말을 듣되 너는 그들에게 엄히 경고하고 그들을 다스릴 왕의 제도를 가르치라',7379),
('1sa-8-10','1sa','사무엘상',8,10,'사무엘이 왕을 요구하는 백성에게 여호와의 모든 말씀을 말하여',7380),
('1sa-8-11','1sa','사무엘상',8,11,'이르되 너희를 다스릴 왕의 제도는 이러하니라 그가 너희 아들들을 데려다가 그의 병거와 말을 어거하게 하리니 그들이 그 병거 앞에서 달릴 것이며',7381),
('1sa-8-12','1sa','사무엘상',8,12,'그가 또 너희의 아들들을 천부장과 오십부장을 삼을 것이며 자기 밭을 갈게 하고 자기 추수를 하게 할 것이며 자기 무기와 병거의 장비도 만들게 할 것이며',7382),
('1sa-8-13','1sa','사무엘상',8,13,'그가 또 너희의 딸들을 데려다가 향료 만드는 자와 요리하는 자와 떡 굽는 자로 삼을 것이며',7383),
('1sa-8-14','1sa','사무엘상',8,14,'그가 또 너희의 밭과 포도원과 감람원에서 제일 좋은 것을 가져다가 자기의 신하들에게 줄 것이며',7384),
('1sa-8-15','1sa','사무엘상',8,15,'그가 또 너희의 곡식과 포도원 소산의 십일조를 거두어 자기의 관리와 신하에게 줄 것이며',7385),
('1sa-8-16','1sa','사무엘상',8,16,'그가 또 너희의 노비와 가장 아름다운 소년과 나귀들을 끌어다가 자기 일을 시킬 것이며',7386),
('1sa-8-17','1sa','사무엘상',8,17,'너희의 양 떼의 십분의 일을 거두어 가리니 너희가 그의 종이 될 것이라',7387),
('1sa-8-18','1sa','사무엘상',8,18,'그 날에 너희는 너희가 택한 왕으로 말미암아 부르짖되 그 날에 여호와께서 너희에게 응답하지 아니하시리라 하니',7388),
('1sa-8-19','1sa','사무엘상',8,19,'백성이 사무엘의 말 듣기를 거절하여 이르되 아니로소이다 우리도 우리 왕이 있어야 하리니',7389),
('1sa-8-20','1sa','사무엘상',8,20,'우리도 다른 나라들 같이 되어 우리의 왕이 우리를 다스리며 우리 앞에 나가서 우리의 싸움을 싸워야 할 것이니이다 하는지라',7390),
('1sa-8-21','1sa','사무엘상',8,21,'사무엘이 백성의 말을 다 듣고 여호와께 아뢰매',7391),
('1sa-8-22','1sa','사무엘상',8,22,'여호와께서 사무엘에게 이르시되 그들의 말을 들어 왕을 세우라 하시니 사무엘이 이스라엘 사람들에게 이르되 너희는 각기 성읍으로 돌아가라 하니라',7392),
('1sa-9-1','1sa','사무엘상',9,1,'베냐민 지파에 기스라 이름하는 유력한 사람이 있으니 그는 아비엘의 아들이요 스롤의 손자요 베고랏의 증손이요 아비아의 현손이며 베냐민 사람이더라',7393),
('1sa-9-2','1sa','사무엘상',9,2,'기스에게 아들이 있으니 그의 이름은 사울이요 준수한 소년이라 이스라엘 자손 중에 그보다 더 준수한 자가 없고 키는 모든 백성보다 어깨 위만큼 더 컸더라',7394),
('1sa-9-3','1sa','사무엘상',9,3,'사울의 아버지 기스가 암나귀들을 잃고 그의 아들 사울에게 이르되 너는 일어나 한 사환을 데리고 가서 암나귀들을 찾으라 하매',7395),
('1sa-9-4','1sa','사무엘상',9,4,'그가 에브라임 산지와 살리사 땅으로 두루 다녀 보았으나 찾지 못하고 사알림 땅으로 두루 다녀 보았으나 그 곳에는 없었고 베냐민 사람의 땅으로 두루 다녀 보았으나 찾지 못하니라',7396),
('1sa-9-5','1sa','사무엘상',9,5,'그들이 숩 땅에 이른 때에 사울이 함께 가던 사환에게 이르되 돌아가자 내 아버지께서 암나귀 생각은 고사하고 우리를 위하여 걱정하실까 두려워하노라 하니',7397),
('1sa-9-6','1sa','사무엘상',9,6,'그가 대답하되 보소서 이 성읍에 하나님의 사람이 있는데 존경을 받는 사람이라 그가 말한 것은 반드시 다 응하나니 그리로 가사이다 그가 혹 우리가 갈 길을 가르쳐 줄까 하나이다 하는지라',7398),
('1sa-9-7','1sa','사무엘상',9,7,'사울이 그의 사환에게 이르되 우리가 가면 그 사람에게 무엇을 드리겠느냐 우리 주머니에 먹을 것이 다하였으니 하나님의 사람에게 드릴 예물이 없도다 무엇이 있느냐 하니',7399),
('1sa-9-8','1sa','사무엘상',9,8,'사환이 사울에게 다시 대답하여 이르되 보소서 내 손에 은 한 세겔의 사분의 일이 있으니 하나님의 사람에게 드려 우리 길을 가르쳐 달라 하겠나이다 하더라',7400),
('1sa-9-9','1sa','사무엘상',9,9,'(옛적 이스라엘에 사람이 하나님께 가서 물으려 하면 말하기를 선견자에게로 가자 하였으니 지금 선지자라 하는 자를 옛적에는 선견자라 일컬었더라)',7401),
('1sa-9-10','1sa','사무엘상',9,10,'사울이 그의 사환에게 이르되 네 말이 옳다 가자 하고 그들이 하나님의 사람이 있는 성읍으로 가니라',7402),
('1sa-9-11','1sa','사무엘상',9,11,'그들이 성읍을 향한 비탈길로 올라가다가 물 길으러 나오는 소녀들을 만나 그들에게 묻되 선견자가 여기 있느냐 하니',7403),
('1sa-9-12','1sa','사무엘상',9,12,'그들이 대답하여 이르되 있나이다 보소서 그가 당신보다 앞서 갔으니 빨리 가소서 백성이 오늘 산당에서 제사를 드리므로 그가 오늘 성읍에 들어오셨나이다',7404),
('1sa-9-13','1sa','사무엘상',9,13,'당신들이 성읍으로 들어가면 그가 먹으러 산당에 올라가기 전에 곧 만나리이다 그가 오기 전에는 백성이 먹지 아니하나니 이는 그가 제물을 축사한 후에야 청함을 받은 자가 먹음이니이다 그러므로 지금 올라가소서 곧 그를 만나리이다 하는지라',7405),
('1sa-9-14','1sa','사무엘상',9,14,'그들이 성읍으로 올라가서 그리로 들어갈 때에 사무엘이 마침 산당으로 올라가려고 마주 나오더라',7406),
('1sa-9-15','1sa','사무엘상',9,15,'사울이 오기 전날에 여호와께서 사무엘에게 알게 하여 이르시되',7407),
('1sa-9-16','1sa','사무엘상',9,16,'내일 이맘 때에 내가 베냐민 땅에서 한 사람을 네게로 보내리니 너는 그에게 기름을 부어 내 백성 이스라엘의 지도자로 삼으라 그가 내 백성을 블레셋 사람들의 손에서 구원하리라 내 백성의 부르짖음이 내게 상달되었으므로 내가 그들을 돌보았노라 하셨더니',7408),
('1sa-9-17','1sa','사무엘상',9,17,'사무엘이 사울을 볼 때에 여호와께서 그에게 이르시되 보라 이는 내가 네게 말한 사람이니 이가 내 백성을 다스리리라 하시니라',7409),
('1sa-9-18','1sa','사무엘상',9,18,'사울이 성문 안 사무엘에게 나아가 이르되 선견자의 집이 어디인지 청하건대 내게 가르치소서 하니',7410),
('1sa-9-19','1sa','사무엘상',9,19,'사무엘이 사울에게 대답하여 이르되 내가 선견자이니라 너는 내 앞서 산당으로 올라가라 너희가 오늘 나와 함께 먹을 것이요 아침에는 내가 너를 보내되 네 마음에 있는 것을 다 네게 말하리라',7411),
('1sa-9-20','1sa','사무엘상',9,20,'사흘 전에 잃은 네 암나귀들을 염려하지 말라 찾았느니라 온 이스라엘이 사모하는 자가 누구냐 너와 네 아버지의 온 집이 아니냐 하는지라',7412),
('1sa-9-21','1sa','사무엘상',9,21,'사울이 대답하여 이르되 나는 이스라엘 지파의 가장 작은 지파 베냐민 사람이 아니니이까 또 나의 가족은 베냐민 지파 모든 가족 중에 가장 미약하지 아니하니이까 당신이 어찌하여 내게 이같이 말씀하시나이까 하니',7413),
('1sa-9-22','1sa','사무엘상',9,22,'사무엘이 사울과 그의 사환을 인도하여 객실로 들어가서 청한 자 중 상석에 앉게 하였는데 객은 삼십 명 가량이었더라',7414),
('1sa-9-23','1sa','사무엘상',9,23,'사무엘이 요리인에게 이르되 내가 네게 주며 네게 두라고 말한 그 부분을 가져오라',7415),
('1sa-9-24','1sa','사무엘상',9,24,'요리인이 넓적다리와 그것에 붙은 것을 가져다가 사울 앞에 놓는지라 사무엘이 이르되 보라 이는 두었던 것이니 네 앞에 놓고 먹으라 내가 백성을 청할 때부터 너를 위하여 이것을 두고 이 때를 기다리게 하였느니라 그 날에 사울이 사무엘과 함께 먹으니라',7416),
('1sa-9-25','1sa','사무엘상',9,25,'그들이 산당에서 내려 성읍에 들어가서는 사무엘이 사울과 함께 지붕에서 담화하고',7417),
('1sa-9-26','1sa','사무엘상',9,26,'그들이 일찍이 일어날새 동틀 때쯤이라 사무엘이 지붕에서 사울을 불러 이르되 일어나라 내가 너를 보내리라 하매 사울이 일어나고 그 두 사람 사울과 사무엘이 함께 밖으로 나가서',7418),
('1sa-9-27','1sa','사무엘상',9,27,'성읍 끝에 이르매 사무엘이 사울에게 이르되 사환에게 우리를 앞서게 하라 하니라 사환이 앞서가므로 또 이르되 너는 이제 잠깐 서 있으라 내가 하나님의 말씀을 네게 들려 주리라 하더라',7419),
('1sa-10-1','1sa','사무엘상',10,1,'이에 사무엘이 기름병을 가져다가 사울의 머리에 붓고 입맞추며 이르되 여호와께서 네게 기름을 부으사 그의 기업의 지도자로 삼지 아니하셨느냐',7420),
('1sa-10-2','1sa','사무엘상',10,2,'네가 오늘 나를 떠나가다가 베냐민 경계 셀사에 있는 라헬의 묘실 곁에서 두 사람을 만나리니 그들이 네게 이르기를 네가 찾으러 갔던 암나귀들을 찾은지라 네 아버지가 암나귀들의 염려는 놓았으나 너희로 말미암아 걱정하여 이르되 내 아들을 위하여 어찌하리요 하더라 할 것이요',7421),
('1sa-10-3','1sa','사무엘상',10,3,'네가 거기서 더 나아가서 다볼 상수리나무에 이르면 거기서 하나님을 뵈오려고 벧엘로 올라가는 세 사람을 만나리니 한 사람은 염소 새끼 셋을 이끌었고 한 사람은 떡 세 덩이를 가졌고 한 사람은 포도주 한 가죽부대를 가진 자라',7422),
('1sa-10-4','1sa','사무엘상',10,4,'그들이 네게 문안하고 떡 두 덩이를 주겠고 너는 그의 손에서 받으리라',7423),
('1sa-10-5','1sa','사무엘상',10,5,'그 후에 네가 하나님의 산에 이르리니 그 곳에는 블레셋 사람들의 영문이 있느니라 네가 그리로 가서 그 성읍으로 들어갈 때에 선지자의 무리가 산당에서부터 비파와 소고와 저와 수금을 앞세우고 예언하며 내려오는 것을 만날 것이요',7424),
('1sa-10-6','1sa','사무엘상',10,6,'네게는 여호와의 영이 크게 임하리니 너도 그들과 함께 예언을 하고 변하여 새 사람이 되리라',7425),
('1sa-10-7','1sa','사무엘상',10,7,'이 징조가 네게 임하거든 너는 기회를 따라 행하라 하나님이 너와 함께 하시느니라',7426),
('1sa-10-8','1sa','사무엘상',10,8,'너는 나보다 앞서 길갈로 내려가라 내가 네게로 내려가서 번제와 화목제를 드리리니 내가 네게 가서 네가 행할 것을 가르칠 때까지 칠 일 동안 기다리라',7427),
('1sa-10-9','1sa','사무엘상',10,9,'그가 사무엘에게서 떠나려고 몸을 돌이킬 때에 하나님이 새 마음을 주셨고 그 날 그 징조도 다 응하니라',7428),
('1sa-10-10','1sa','사무엘상',10,10,'그들이 산에 이를 때에 선지자의 무리가 그를 영접하고 하나님의 영이 사울에게 크게 임하므로 그가 그들 중에서 예언을 하니',7429),
('1sa-10-11','1sa','사무엘상',10,11,'전에 사울을 알던 모든 사람들이 사울이 선지자들과 함께 예언함을 보고 서로 이르되 기스의 아들에게 무슨 일이 일어났느냐 사울도 선지자들 중에 있느냐 하고',7430),
('1sa-10-12','1sa','사무엘상',10,12,'그 곳의 어떤 사람은 말하여 이르되 그들의 아버지가 누구냐 한지라 그러므로 속담이 되어 이르되 사울도 선지자들 중에 있느냐 하더라',7431),
('1sa-10-13','1sa','사무엘상',10,13,'사울이 예언하기를 마치고 산당으로 가니라',7432),
('1sa-10-14','1sa','사무엘상',10,14,'사울의 숙부가 사울과 그의 사환에게 이르되 너희가 어디로 갔더냐 사울이 이르되 암나귀들을 찾다가 찾지 못하므로 사무엘에게 갔었나이다 하니',7433),
('1sa-10-15','1sa','사무엘상',10,15,'사울의 숙부가 이르되 청하노니 사무엘이 너희에게 이른 말을 내게 말하라 하니라',7434),
('1sa-10-16','1sa','사무엘상',10,16,'사울이 그의 숙부에게 말하되 그가 암나귀들을 찾았다고 우리에게 분명히 말하더이다 하고 사무엘이 말하던 나라의 일은 말하지 아니하니라',7435),
('1sa-10-17','1sa','사무엘상',10,17,'사무엘이 백성을 미스바로 불러 여호와 앞에 모으고',7436),
('1sa-10-18','1sa','사무엘상',10,18,'이스라엘 자손에게 이르되 이스라엘 하나님 여호와께서 이같이 말씀하시기를 내가 이스라엘을 애굽에서 인도하여 내고 너희를 애굽인의 손과 너희를 압제하는 모든 나라의 손에서 건져내었느니라 하셨거늘',7437),
('1sa-10-19','1sa','사무엘상',10,19,'너희는 너희를 모든 재난과 고통 중에서 친히 구원하여 내신 너희의 하나님을 오늘 버리고 이르기를 우리 위에 왕을 세우라 하는도다 그런즉 이제 너희의 지파대로 천 명씩 여호와 앞에 나아오라 하고',7438),
('1sa-10-20','1sa','사무엘상',10,20,'사무엘이 이에 이스라엘 모든 지파를 가까이 오게 하였더니 베냐민 지파가 뽑혔고',7439),
('1sa-10-21','1sa','사무엘상',10,21,'베냐민 지파를 그들의 가족별로 가까이 오게 하였더니 마드리의 가족이 뽑혔고 그 중에서 기스의 아들 사울이 뽑혔으나 그를 찾아도 찾지 못한지라',7440),
('1sa-10-22','1sa','사무엘상',10,22,'그러므로 그들이 또 여호와께 묻되 그 사람이 여기 왔나이까 여호와께서 대답하시되 그가 짐보따리들 사이에 숨었느니라 하셨더라',7441),
('1sa-10-23','1sa','사무엘상',10,23,'그들이 달려 가서 거기서 그를 데려오매 그가 백성 중에 서니 다른 사람보다 어깨 위만큼 컸더라',7442),
('1sa-10-24','1sa','사무엘상',10,24,'사무엘이 모든 백성에게 이르되 너희는 여호와께서 택하신 자를 보느냐 모든 백성 중에 짝할 이가 없느니라 하니 모든 백성이 왕의 만세를 외쳐 부르니라',7443),
('1sa-10-25','1sa','사무엘상',10,25,'사무엘이 나라의 제도를 백성에게 말하고 책에 기록하여 여호와 앞에 두고 모든 백성을 각기 집으로 보내매',7444),
('1sa-10-26','1sa','사무엘상',10,26,'사울도 기브아 자기 집으로 갈 때에 마음이 하나님께 감동된 유력한 자들과 함께 갔느니라',7445),
('1sa-10-27','1sa','사무엘상',10,27,'어떤 불량배는 이르되 이 사람이 어떻게 우리를 구원하겠느냐 하고 멸시하며 예물을 바치지 아니하였으나 그는 잠잠하였더라',7446),
('1sa-11-1','1sa','사무엘상',11,1,'암몬 사람 나하스가 올라와서 길르앗 야베스에 맞서 진 치매 야베스 모든 사람들이 나하스에게 이르되 우리와 언약하자 그리하면 우리가 너를 섬기리라 하니',7447),
('1sa-11-2','1sa','사무엘상',11,2,'암몬 사람 나하스가 그들에게 이르되 내가 너희 오른 눈을 다 빼야 너희와 언약하리라 내가 온 이스라엘을 이같이 모욕하리라',7448),
('1sa-11-3','1sa','사무엘상',11,3,'야베스 장로들이 그에게 이르되 우리에게 이레 동안 말미를 주어 우리가 이스라엘 온 지역에 전령들을 보내게 하라 만일 우리를 구원할 자가 없으면 네게 나아가리라 하니라',7449),
('1sa-11-4','1sa','사무엘상',11,4,'이에 전령들이 사울이 사는 기브아에 이르러 이 말을 백성에게 전하매 모든 백성이 소리를 높여 울더니',7450),
('1sa-11-5','1sa','사무엘상',11,5,'마침 사울이 밭에서 소를 몰고 오다가 이르되 백성이 무슨 일로 우느냐 하니 그들이 야베스 사람의 말을 전하니라',7451),
('1sa-11-6','1sa','사무엘상',11,6,'사울이 이 말을 들을 때에 하나님의 영에게 크게 감동되매 그의 노가 크게 일어나',7452),
('1sa-11-7','1sa','사무엘상',11,7,'한 겨리의 소를 잡아 각을 뜨고 전령들의 손으로 그것을 이스라엘 모든 지역에 두루 보내어 이르되 누구든지 나와서 사울과 사무엘을 따르지 아니하면 그의 소들도 이와 같이 하리라 하였더니 여호와의 두려움이 백성에게 임하매 그들이 한 사람 같이 나온지라',7453),
('1sa-11-8','1sa','사무엘상',11,8,'사울이 베섹에서 그들의 수를 세어 보니 이스라엘 자손이 삼십만 명이요 유다 사람이 삼만 명이더라',7454),
('1sa-11-9','1sa','사무엘상',11,9,'무리가 모든 전령들에게 이르되 너희는 길르앗 야베스 사람에게 이같이 이르기를 내일 해가 더울 때에 너희가 구원을 받으리라 하라 전령들이 돌아가서 야베스 사람들에게 전하매 그들이 기뻐하니라',7455),
('1sa-11-10','1sa','사무엘상',11,10,'야베스 사람들이 이에 이르되 우리가 내일 너희에게 나아가리니 너희 생각에 좋을 대로 우리에게 다 행하라 하니라',7456),
('1sa-11-11','1sa','사무엘상',11,11,'이튿날 사울이 백성을 삼 대로 나누고 새벽에 적진 한가운데로 들어가서 날이 더울 때까지 암몬 사람들을 치매 남은 자가 다 흩어져서 둘도 함께 한 자가 없었더라',7457),
('1sa-11-12','1sa','사무엘상',11,12,'백성이 사무엘에게 이르되 사울이 어찌 우리를 다스리겠느냐 한 자가 누구니이까 그들을 끌어내소서 우리가 죽이겠나이다',7458),
('1sa-11-13','1sa','사무엘상',11,13,'사울이 이르되 이 날에는 사람을 죽이지 못하리니 여호와께서 오늘 이스라엘 중에 구원을 베푸셨음이니라',7459),
('1sa-11-14','1sa','사무엘상',11,14,'사무엘이 백성에게 이르되 오라 우리가 길갈로 가서 나라를 새롭게 하자',7460),
('1sa-11-15','1sa','사무엘상',11,15,'모든 백성이 길갈로 가서 거기서 여호와 앞에서 사울을 왕으로 삼고 길갈에서 여호와 앞에 화목제를 드리고 사울과 이스라엘 모든 사람이 거기서 크게 기뻐하니라',7461),
('1sa-12-1','1sa','사무엘상',12,1,'사무엘이 온 이스라엘에게 이르되 보라 너희가 내게 한 말을 내가 다 듣고 너희 위에 왕을 세웠더니',7462),
('1sa-12-2','1sa','사무엘상',12,2,'이제 왕이 너희 앞에 출입하느니라 보라 나는 늙어 머리가 희어졌고 내 아들들도 너희와 함께 있느니라 내가 어려서부터 오늘까지 너희 앞에 출입하였거니와',7463),
('1sa-12-3','1sa','사무엘상',12,3,'내가 여기 있나니 여호와 앞과 그의 기름 부음을 받은 자 앞에서 내게 대하여 증언하라 내가 누구의 소를 빼앗았느냐 누구의 나귀를 빼앗았느냐 누구를 속였느냐 누구를 압제하였느냐 내 눈을 흐리게 하는 뇌물을 누구의 손에서 받았느냐 그리하였으면 내가 그것을 너희에게 갚으리라 하니',7464),
('1sa-12-4','1sa','사무엘상',12,4,'그들이 이르되 당신이 우리를 속이지 아니하였고 압제하지 아니하였고 누구의 손에서든지 아무것도 빼앗은 것이 없나이다 하니라',7465),
('1sa-12-5','1sa','사무엘상',12,5,'사무엘이 백성에게 이르되 너희가 내 손에서 아무것도 찾아낸 것이 없음을 여호와께서 너희에게 대하여 증언하시며 그의 기름 부음을 받은 자도 오늘 증언하느니라 하니 그들이 이르되 그가 증언하시나이다 하니라',7466),
('1sa-12-6','1sa','사무엘상',12,6,'사무엘이 백성에게 이르되 모세와 아론을 세우시며 너희 조상들을 애굽 땅에서 인도하여 내신 이는 여호와이시니',7467),
('1sa-12-7','1sa','사무엘상',12,7,'그런즉 가만히 서 있으라 여호와께서 너희와 너희 조상들에게 행하신 모든 공의로운 일에 대하여 내가 여호와 앞에서 너희와 담론하리라',7468),
('1sa-12-8','1sa','사무엘상',12,8,'야곱이 애굽에 들어간 후 너희 조상들이 여호와께 부르짖으매 여호와께서 모세와 아론을 보내사 그 두 사람으로 너희 조상들을 애굽에서 인도해 내어 이 곳에 살게 하셨으나',7469),
('1sa-12-9','1sa','사무엘상',12,9,'그들이 그들의 하나님 여호와를 잊은지라 여호와께서 그들을 하솔 군사령관 시스라의 손과 블레셋 사람들의 손과 모압 왕의 손에 넘기셨더니 그들이 저희를 치매',7470),
('1sa-12-10','1sa','사무엘상',12,10,'백성이 여호와께 부르짖어 이르되 우리가 여호와를 버리고 바알들과 아스다롯을 섬김으로 범죄하였나이다 그러하오나 이제 우리를 원수들의 손에서 건져내소서 그리하시면 우리가 주를 섬기겠나이다 하매',7471),
('1sa-12-11','1sa','사무엘상',12,11,'여호와께서 여룹바알과 베단과 입다와 나 사무엘을 보내사 너희를 너희 사방 원수의 손에서 건져내사 너희에게 안전하게 살게 하셨거늘',7472),
('1sa-12-12','1sa','사무엘상',12,12,'너희가 암몬 자손의 왕 나하스가 너희를 치러 옴을 보고 너희의 하나님 여호와께서는 너희의 왕이 되심에도 불구하고 너희가 내게 이르기를 아니라 우리를 다스릴 왕이 있어야 하겠다 하였도다',7473),
('1sa-12-13','1sa','사무엘상',12,13,'이제 너희가 구한 왕, 너희가 택한 왕을 보라 여호와께서 너희 위에 왕을 세우셨느니라',7474),
('1sa-12-14','1sa','사무엘상',12,14,'너희가 만일 여호와를 경외하여 그를 섬기며 그의 목소리를 듣고 여호와의 명령을 거역하지 아니하며 또 너희와 너희를 다스리는 왕이 너희의 하나님 여호와를 따르면 좋겠지마는',7475),
('1sa-12-15','1sa','사무엘상',12,15,'너희가 만일 여호와의 목소리를 듣지 아니하고 여호와의 명령을 거역하면 여호와의 손이 너희의 조상들을 치신 것 같이 너희를 치실 것이라',7476),
('1sa-12-16','1sa','사무엘상',12,16,'너희는 이제 가만히 서서 여호와께서 너희 목전에서 행하시는 이 큰 일을 보라',7477),
('1sa-12-17','1sa','사무엘상',12,17,'오늘은 밀 베는 때가 아니냐 내가 여호와께 아뢰리니 여호와께서 우레와 비를 보내사 너희가 왕을 구한 일 곧 여호와의 목전에서 범한 죄악이 큼을 너희에게 밝히 알게 하시리라',7478),
('1sa-12-18','1sa','사무엘상',12,18,'이에 사무엘이 여호와께 아뢰매 여호와께서 그 날에 우레와 비를 보내시니 모든 백성이 여호와와 사무엘을 크게 두려워하니라',7479),
('1sa-12-19','1sa','사무엘상',12,19,'모든 백성이 사무엘에게 이르되 당신의 종들을 위하여 당신의 하나님 여호와께 기도하여 우리가 죽지 않게 하소서 우리가 우리의 모든 죄에 왕을 구하는 악을 더하였나이다',7480),
('1sa-12-20','1sa','사무엘상',12,20,'사무엘이 백성에게 이르되 두려워하지 말라 너희가 과연 이 모든 악을 행하였으나 여호와를 따르는 데에서 돌아서지 말고 오직 너희의 마음을 다하여 여호와를 섬기라',7481),
('1sa-12-21','1sa','사무엘상',12,21,'돌아서서 유익하게도 못하며 구원하지도 못하는 헛된 것을 따르지 말라 그들은 헛되니라',7482),
('1sa-12-22','1sa','사무엘상',12,22,'여호와께서는 너희를 자기 백성으로 삼으신 것을 기뻐하셨으므로 여호와께서는 그의 크신 이름을 위해서라도 자기 백성을 버리지 아니하실 것이요',7483),
('1sa-12-23','1sa','사무엘상',12,23,'나는 너희를 위하여 기도하기를 쉬는 죄를 여호와 앞에 결단코 범하지 아니하고 선하고 의로운 길을 너희에게 가르칠 것인즉',7484),
('1sa-12-24','1sa','사무엘상',12,24,'너희는 여호와께서 너희를 위하여 행하신 그 큰 일을 생각하여 오직 그를 경외하며 너희의 마음을 다하여 진실히 섬기라',7485),
('1sa-12-25','1sa','사무엘상',12,25,'만일 너희가 여전히 악을 행하면 너희와 너희 왕이 다 멸망하리라',7486),
('1sa-13-1','1sa','사무엘상',13,1,'사울이 왕이 될 때에 사십 세라 그가 이스라엘을 다스린 지 이 년에',7487),
('1sa-13-2','1sa','사무엘상',13,2,'이스라엘 사람 삼천 명을 택하여 그 중에서 이천 명은 자기와 함께 믹마스와 벧엘 산에 있게 하고 일천 명은 요나단과 함께 베냐민 기브아에 있게 하고 남은 백성은 각기 장막으로 보내니라',7488),
('1sa-13-3','1sa','사무엘상',13,3,'요나단이 게바에 있는 블레셋 사람의 수비대를 치매 블레셋 사람이 이를 들은지라 사울이 온 땅에 나팔을 불어 이르되 히브리 사람들은 들으라 하니',7489),
('1sa-13-4','1sa','사무엘상',13,4,'온 이스라엘이 사울이 블레셋 사람들의 수비대를 친 것과 이스라엘이 블레셋 사람들의 미움을 받게 되었다 함을 듣고 그 백성이 길갈로 모여 사울을 따르니라',7490),
('1sa-13-5','1sa','사무엘상',13,5,'블레셋 사람들이 이스라엘과 싸우려고 모였는데 병거가 삼만이요 마병이 육천 명이요 백성은 해변의 모래 같이 많더라 그들이 올라와 벧아웬 동쪽 믹마스에 진 치매',7491),
('1sa-13-6','1sa','사무엘상',13,6,'이스라엘 사람들이 위급함을 보고 절박하여 굴과 수풀과 바위 틈과 은밀한 곳과 웅덩이에 숨으며',7492),
('1sa-13-7','1sa','사무엘상',13,7,'어떤 히브리 사람들은 요단을 건너 갓과 길르앗 땅으로 가되 사울은 아직 길갈에 있고 그를 따른 모든 백성은 떨더라',7493),
('1sa-13-8','1sa','사무엘상',13,8,'사울은 사무엘이 정한 기한대로 이레 동안을 기다렸으나 사무엘이 길갈로 오지 아니하매 백성이 사울에게서 흩어지는지라',7494),
('1sa-13-9','1sa','사무엘상',13,9,'사울이 이르되 번제와 화목제물을 이리로 가져오라 하여 번제를 드렸더니',7495),
('1sa-13-10','1sa','사무엘상',13,10,'번제 드리기를 마치자 사무엘이 온지라 사울이 나가 맞으며 문안하매',7496),
('1sa-13-11','1sa','사무엘상',13,11,'사무엘이 이르되 왕이 행하신 것이 무엇이냐 하니 사울이 이르되 백성은 내게서 흩어지고 당신은 정한 날 안에 오지 아니하고 블레셋 사람은 믹마스에 모였음을 내가 보았으므로',7497),
('1sa-13-12','1sa','사무엘상',13,12,'이에 내가 이르기를 블레셋 사람들이 나를 치러 길갈로 내려오겠거늘 내가 여호와께 은혜를 간구하지 못하였다 하고 부득이하여 번제를 드렸나이다 하니라',7498),
('1sa-13-13','1sa','사무엘상',13,13,'사무엘이 사울에게 이르되 왕이 망령되이 행하였도다 왕이 왕의 하나님 여호와께서 왕에게 내리신 명령을 지키지 아니하였도다 그리하였더라면 여호와께서 이스라엘 위에 왕의 나라를 영원히 세우셨을 것이거늘',7499),
('1sa-13-14','1sa','사무엘상',13,14,'지금은 왕의 나라가 길지 못할 것이라 여호와께서 왕에게 명령하신 바를 왕이 지키지 아니하였으므로 여호와께서 그의 마음에 맞는 사람을 구하여 여호와께서 그를 그의 백성의 지도자로 삼으셨느니라 하고',7500)
